# Reuse outbound HTTP connections instead of opening a new TCP/TLS connection
# for every Supabase/Telegram request. Automatic retries are restricted to
# idempotent methods so publishing or modifying listings is never duplicated.
HTTP_SESSION = requests.Session()
_HTTP_RETRY = Retry(
    total=2,
    connect=2,
    read=1,
    status=2,
    backoff_factor=0.35,
    status_forcelist=(429, 500, 502, 503, 504),
    allowed_methods=frozenset({"GET", "HEAD", "OPTIONS"}),
    respect_retry_after_header=True,
)
_HTTP_ADAPTER = HTTPAdapter(
    pool_connections=32,
    pool_maxsize=64,
    max_retries=_HTTP_RETRY,
    pool_block=False,
)
HTTP_SESSION.mount("https://", _HTTP_ADAPTER)

# Small shared pool lets independent Mini App reads overlap without creating
# a new thread pool for every request.
LISTING_READ_EXECUTOR = ThreadPoolExecutor(max_workers=8)
HTTP_SESSION.mount("http://", _HTTP_ADAPTER)

