def _utc_now_iso():
    """UTC timestamp for PostgREST expiry filters and listing lifecycle dates."""
    return datetime.now(timezone.utc).isoformat()


def supabase_enabled():
    return bool(SUPABASE_URL and SUPABASE_SECRET_KEY)


def supabase_request(method, path, params=None, payload=None):
    if not supabase_enabled():
        return None

    url = f"{SUPABASE_URL}/rest/v1/{path.lstrip('/')}"
    headers = {
        "apikey": SUPABASE_SECRET_KEY,
        "Authorization": f"Bearer {SUPABASE_SECRET_KEY}",
        "Content-Type": "application/json",
    }

    if method.upper() in {"POST", "PATCH", "DELETE"}:
        headers["Prefer"] = "return=representation"

    # Diagnostic-only timing for the cursor RPC. This logs timings and response
    # metadata only; it does not alter the request, payload, result, or error path.
    _is_cursor_rpc = method.upper() == "POST" and path.lstrip("/") == "rpc/mm_search_cursor_listings"
    _rpc_started = time.perf_counter() if _is_cursor_rpc else None
    try:
        response = HTTP_SESSION.request(
            method.upper(),
            url,
            headers=headers,
            params=params or {},
            json=payload,
            timeout=(5, 20),
        )
        _rpc_request_ms = (time.perf_counter() - _rpc_started) * 1000 if _is_cursor_rpc else None
        if not response.ok:
            global LAST_SUPABASE_ERROR
            LAST_SUPABASE_ERROR = f"HTTP {response.status_code}: {response.text[:700]}"
            if _is_cursor_rpc:
                print(
                    "PERF supabase_rpc_transport"
                    f" request_total_ms={_rpc_request_ms:.1f}"
                    f" response_elapsed_ms={response.elapsed.total_seconds() * 1000:.1f}"
                    f" status={response.status_code}"
                    f" bytes={len(response.content)}"
                    f" upstream_ms={response.headers.get('x-kong-upstream-latency', 'na')}"
                    f" gateway_ms={response.headers.get('x-kong-proxy-latency', 'na')}"
                )
            print(
                "SUPABASE ERROR:",
                response.status_code,
                response.text[:1000],
            )
            return None

        if not response.text:
            if _is_cursor_rpc:
                print(f"PERF supabase_rpc_transport request_total_ms={_rpc_request_ms:.1f} status={response.status_code} bytes=0 json_parse_ms=0.0")
            return []

        _json_started = time.perf_counter() if _is_cursor_rpc else None
        result = response.json()
        if _is_cursor_rpc:
            _json_parse_ms = (time.perf_counter() - _json_started) * 1000
            print(
                "PERF supabase_rpc_transport"
                f" request_total_ms={_rpc_request_ms:.1f}"
                f" response_elapsed_ms={response.elapsed.total_seconds() * 1000:.1f}"
                f" json_parse_ms={_json_parse_ms:.1f}"
                f" status={response.status_code}"
                f" bytes={len(response.content)}"
                f" upstream_ms={response.headers.get('x-kong-upstream-latency', 'na')}"
                f" gateway_ms={response.headers.get('x-kong-proxy-latency', 'na')}"
            )
        return result
    except Exception as error:
        if _is_cursor_rpc:
            _rpc_elapsed_ms = (time.perf_counter() - _rpc_started) * 1000
            print(f"PERF supabase_rpc_transport exception_total_ms={_rpc_elapsed_ms:.1f} error_type={type(error).__name__}")
        LAST_SUPABASE_ERROR = f"REQUEST ERROR: {repr(error)}"
        print("SUPABASE REQUEST ERROR:", repr(error))
        return None



# ============================================================
# УСТОЙЧИВОЕ ХРАНЕНИЕ СОСТОЯНИЯ БОТА В SUPABASE
# Требуется таблица public.mm_bot_runtime_state из SQL-миграции.
# ============================================================

RUNTIME_STATE_TABLE = "mm_bot_runtime_state"

# Telegram may redeliver the same webhook update. A dedicated table with a
# unique update_id lets us claim an update atomically across Render restarts.
TELEGRAM_UPDATES_TABLE = "mm_telegram_updates"
_telegram_update_claim_count = 0


def claim_telegram_update(update_id):
    """Return True for a new update, False for a duplicate, None on DB failure."""
    global _telegram_update_claim_count
    if update_id is None or not supabase_enabled():
        return None
    url = f"{SUPABASE_URL}/rest/v1/{TELEGRAM_UPDATES_TABLE}"
    headers = {
        "apikey": SUPABASE_SECRET_KEY,
        "Authorization": f"Bearer {SUPABASE_SECRET_KEY}",
        "Content-Type": "application/json",
        "Prefer": "resolution=ignore-duplicates,return=representation",
    }
    try:
        response = HTTP_SESSION.post(
            url,
            params={"on_conflict": "update_id"},
            headers=headers,
            json={"update_id": int(update_id)},
            timeout=(5, 10),
        )
        if not response.ok:
            print("TELEGRAM UPDATE DEDUP ERROR:", response.status_code, response.text[:500])
            return None
        rows = response.json() if response.text else []
        if not rows:
            print("TELEGRAM DUPLICATE UPDATE IGNORED:", update_id)
            return False
        _telegram_update_claim_count += 1
        # Keep the receipt table bounded; cleanup is infrequent, not per update.
        if _telegram_update_claim_count % 1000 == 0:
            try:
                cutoff = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - 7 * 86400))
                supabase_request(
                    "DELETE", TELEGRAM_UPDATES_TABLE,
                    params={"created_at": f"lt.{cutoff}"},
                )
            except Exception as cleanup_error:
                print("TELEGRAM UPDATE CLEANUP WARNING:", repr(cleanup_error))
        return True
    except Exception as error:
        print("TELEGRAM UPDATE DEDUP REQUEST ERROR:", repr(error))
        return None


def runtime_state_load(state_key):
    """Load one JSON state record. Returns (found, payload, request_ok)."""
    if not supabase_enabled():
        return False, None, False
    result = supabase_request(
        "GET",
        RUNTIME_STATE_TABLE,
        params={"select": "payload", "state_key": f"eq.{state_key}", "limit": "1"},
    )
    if result is None:
        return False, None, False
    if not result:
        return False, None, True
    payload = result[0].get("payload")
    return True, payload, True


def runtime_state_save(state_key, payload):
    """Upsert a JSON state record using the service-role credential."""
    if not supabase_enabled():
        return False
    url = f"{SUPABASE_URL}/rest/v1/{RUNTIME_STATE_TABLE}"
    headers = {
        "apikey": SUPABASE_SECRET_KEY,
        "Authorization": f"Bearer {SUPABASE_SECRET_KEY}",
        "Content-Type": "application/json",
        "Prefer": "resolution=merge-duplicates,return=minimal",
    }
    try:
        response = HTTP_SESSION.post(
            url,
            params={"on_conflict": "state_key"},
            headers=headers,
            json={
                "state_key": str(state_key),
                "payload": payload,
                "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            },
            timeout=(5, 20),
        )
        if not response.ok:
            print("RUNTIME STATE SAVE ERROR:", response.status_code, response.text[:700])
            return False
        return True
    except Exception as error:
        print("RUNTIME STATE SAVE REQUEST ERROR:", repr(error))
        return False


def runtime_state_delete(state_key):
    if not supabase_enabled():
        return False
    result = supabase_request(
        "DELETE",
        RUNTIME_STATE_TABLE,
        params={"state_key": f"eq.{state_key}"},
    )
    return result is not None


def _runtime_key(prefix, identifier):
    return f"{prefix}:{identifier}"


def _load_runtime_record(prefix, identifier, target, target_key, loaded_keys):
    key = _runtime_key(prefix, identifier)
    found, payload, ok = runtime_state_load(key)
    if not ok:
        return None
    loaded_keys.add(key)
    if found and isinstance(payload, dict):
        target[target_key] = payload
        return payload
    target.pop(target_key, None)
    return None


def _sync_runtime_record(prefix, identifier, target, target_key, loaded_keys):
    key = _runtime_key(prefix, identifier)
    if target_key in target:
        if not runtime_state_save(key, target[target_key]):
            print("RUNTIME STATE WARNING: record not persisted:", key)
    elif key in loaded_keys:
        if not runtime_state_delete(key):
            print("RUNTIME STATE WARNING: record not deleted:", key)


def _runtime_request_id(callback_data):
    match = re.match(
        r"^mod_(?:edit|publish|reject|field_[a-z]+|details|detail|back|queue_open)_(\d+)(?:_|$)",
        str(callback_data or ""),
    )
    return int(match.group(1)) if match else None


def _load_runtime_for_update(update):
    """Restore only records related to this Telegram update, not the whole table."""
    loaded = {"states": set(), "moderation": set(), "sessions": set(), "support_replies": set()}
    chat_id = None
    callback_from_id = None
    callback_data = ""

    if isinstance(update.get("message"), dict):
        chat_id = update["message"].get("chat", {}).get("id")
    elif isinstance(update.get("callback_query"), dict):
        callback = update["callback_query"]
        chat_id = callback.get("message", {}).get("chat", {}).get("id")
        callback_from_id = callback.get("from", {}).get("id")
        callback_data = callback.get("data", "")

    if chat_id is not None:
        _load_runtime_record("user", chat_id, states, chat_id, loaded["states"])
        if str(chat_id) == str(ADMIN_CHAT_ID):
            _load_runtime_record("moderator", chat_id, moderator_sessions, chat_id, loaded["sessions"])
        if str(chat_id) in ADMIN_TELEGRAM_IDS or str(chat_id) == str(ADMIN_CHAT_ID):
            _load_runtime_record("support_reply", chat_id, support_reply_sessions, chat_id, loaded["support_replies"])

    # Admin callbacks can refer to a moderation request belonging to another user.
    request_id = _runtime_request_id(callback_data)
    if request_id is not None:
        item = _load_runtime_record(
            "moderation", request_id, moderation_requests, request_id, loaded["moderation"]
        )
        if item and item.get("user_chat_id") is not None:
            user_id = item["user_chat_id"]
            _load_runtime_record("user", user_id, states, user_id, loaded["states"])

    # If this is a moderator's text reply, restore the request and its author's state.
    if chat_id is not None and chat_id in moderator_sessions:
        session = moderator_sessions[chat_id]
        session_request_id = session.get("request_id") if isinstance(session, dict) else None
        if session_request_id is not None:
            item = _load_runtime_record(
                "moderation", session_request_id, moderation_requests,
                session_request_id, loaded["moderation"]
            )
            if item and item.get("user_chat_id") is not None:
                user_id = item["user_chat_id"]
                _load_runtime_record("user", user_id, states, user_id, loaded["states"])

    loaded["counter_before"] = next_moderation_id
    return loaded, chat_id, callback_from_id, request_id


def _save_runtime_after_update(loaded, chat_id, callback_from_id, request_id):
    for key in loaded["states"]:
        # Keys are strings such as user:123; the dict key remains numeric where possible.
        raw_id = key.split(":", 1)[1]
        target_key = next((k for k in states if str(k) == raw_id), None)
        if target_key is None:
            try:
                candidate = int(raw_id)
            except ValueError:
                candidate = raw_id
            target_key = candidate
        _sync_runtime_record("user", raw_id, states, target_key, loaded["states"])

    for key in loaded["moderation"]:
        raw_id = key.split(":", 1)[1]
        try:
            target_key = int(raw_id)
        except ValueError:
            target_key = raw_id
        _sync_runtime_record("moderation", raw_id, moderation_requests, target_key, loaded["moderation"])

    # Persist moderation requests created during this update (for example, when
    # the user submits a listing) even though their IDs were not loaded before.
    if chat_id is not None:
        for current_id, item in list(moderation_requests.items()):
            if str(item.get("user_chat_id")) == str(chat_id):
                key = _runtime_key("moderation", current_id)
                if key not in loaded["moderation"]:
                    if not runtime_state_save(key, item):
                        print("RUNTIME STATE WARNING: new moderation request not persisted:", key)

    for key in loaded["sessions"]:
        raw_id = key.split(":", 1)[1]
        target_key = next((k for k in moderator_sessions if str(k) == raw_id), None)
        if target_key is None:
            try:
                target_key = int(raw_id)
            except ValueError:
                target_key = raw_id
        _sync_runtime_record("moderator", raw_id, moderator_sessions, target_key, loaded["sessions"])

    for key in loaded["support_replies"]:
        raw_id = key.split(":", 1)[1]
        target_key = next((k for k in support_reply_sessions if str(k) == raw_id), None)
        if target_key is None:
            try:
                target_key = int(raw_id)
            except ValueError:
                target_key = raw_id
        _sync_runtime_record("support_reply", raw_id, support_reply_sessions, target_key, loaded["support_replies"])

    if next_moderation_id != loaded.get("counter_before", next_moderation_id):
        if not runtime_state_save("meta:next_moderation_id", {"value": next_moderation_id}):
            print("RUNTIME STATE WARNING: moderation counter not persisted")


def _supabase_exact_count(path, params=None):
    """Return an exact PostgREST count without downloading every matching row.

    Returns None when the server/proxy does not provide Content-Range so callers
    can retain their legacy compatibility path during rollout.
    """
    if not supabase_enabled():
        return None

    url = f"{SUPABASE_URL}/rest/v1/{path.lstrip('/')}"
    headers = {
        "apikey": SUPABASE_SECRET_KEY,
        "Authorization": f"Bearer {SUPABASE_SECRET_KEY}",
        "Prefer": "count=exact",
        "Range-Unit": "items",
        "Range": "0-0",
    }
    query = {"select": "id"}
    if params:
        query.update(params)

    try:
        response = HTTP_SESSION.request(
            "HEAD", url, headers=headers, params=query, timeout=(5, 20)
        )
        if not response.ok:
            print("SUPABASE COUNT ERROR:", response.status_code, path)
            return None
        content_range = str(response.headers.get("Content-Range", ""))
        total = content_range.rsplit("/", 1)[-1].strip()
        if total.isdigit():
            return int(total)
        return None
    except Exception as error:
        print("SUPABASE COUNT REQUEST ERROR:", path, repr(error))
        return None


def _supabase_fetch_all_bounded(path, params=None, batch_size=1000, max_rows=100000, order="id.asc"):
    """Fetch all matching rows in stable pages, or return None if completeness cannot be proven.

    This is a compatibility fallback only. Normal dashboard paths should use exact
    counts or SQL aggregation. A result reaching max_rows is treated as potentially
    truncated rather than reported as a complete total.
    """
    if not supabase_enabled():
        return None
    try:
        batch_size = max(1, min(int(batch_size), 1000))
        max_rows = max(batch_size, int(max_rows))
    except (TypeError, ValueError):
        batch_size, max_rows = 1000, 100000
    collected = []
    base = dict(params or {})
    base.setdefault("order", order)
    offset = 0
    while offset < max_rows:
        page_params = dict(base)
        page_params["offset"] = str(offset)
        page_params["limit"] = str(min(batch_size, max_rows - offset))
        page = supabase_request("GET", path, params=page_params)
        if not isinstance(page, list):
            return None
        if not page:
            return collected
        collected.extend(page)
        if len(page) < int(page_params["limit"]):
            return collected
        offset += len(page)
    # Exactly at the safety ceiling: there may be more rows, so do not claim completeness.
    print("SUPABASE FALLBACK READ INCOMPLETE: safety ceiling reached for", path)
    return None


def load_local_published_listings():
    global published_listings, next_listing_id

    try:
        with open(LISTINGS_FILE, "r", encoding="utf-8") as file:
            payload = json.load(file)

        if isinstance(payload, dict):
            published_listings = payload.get("listings", [])
            next_listing_id = int(payload.get("next_id", 1))
        elif isinstance(payload, list):
            published_listings = payload
            next_listing_id = 1
        else:
            published_listings = []
            next_listing_id = 1

        if not isinstance(published_listings, list):
            published_listings = []

        if published_listings:
            max_id = max(
                int(item.get("id", 0))
                for item in published_listings
                if str(item.get("id", "")).isdigit()
            )
            next_listing_id = max(next_listing_id, max_id + 1)

    except (FileNotFoundError, json.JSONDecodeError, OSError, ValueError, TypeError):
        published_listings = []
        next_listing_id = 1


def save_local_published_listings():
    payload = {
        "next_id": next_listing_id,
        "listings": published_listings,
    }

    try:
        directory = os.path.dirname(LISTINGS_FILE)
        if directory:
            os.makedirs(directory, exist_ok=True)

        temporary = LISTINGS_FILE + ".tmp"
        with open(temporary, "w", encoding="utf-8") as file:
            json.dump(payload, file, ensure_ascii=False, indent=2)

        os.replace(temporary, LISTINGS_FILE)
        return True
    except OSError as error:
        print("LISTINGS SAVE ERROR:", repr(error))
        return False


def _normalize_price_input(value):
    """Accept numeric prices only; allow spaces as thousands separators and up to 2 decimals."""
    raw = str(value or "").strip()
    cleaned = re.sub(r"\s+", "", raw).replace(",", ".")
    if not re.fullmatch(r"\d+(?:\.\d{1,2})?", cleaned):
        return None
    return cleaned


def _price_number(value):
    try:
        if value in (None, "", "Бесплатно"):
            return None
        cleaned = str(value).replace(" ", "").replace(",", ".")
        if not re.fullmatch(r"\d+(?:\.\d{1,2})?", cleaned):
            return None
        return float(cleaned)
    except (TypeError, ValueError):
        return None


# City IDs are stable reference data. Cache only successful lookups so a
# temporary Supabase failure never gets cached as a missing city.
_SUPABASE_CITY_ID_CACHE = {}
_SUPABASE_USER_ID_CACHE = {}
_SUPABASE_ID_CACHE_LOCK = threading.Lock()


def _supabase_city_id(slug_value):
    slug_value = _canonical_city_slug(slug_value)
    with _SUPABASE_ID_CACHE_LOCK:
        cached_id = _SUPABASE_CITY_ID_CACHE.get(slug_value)
    if cached_id is not None:
        return cached_id

    rows = supabase_request(
        "GET",
        "cities",
        params={
            "select": "id,slug",
            "slug": f"eq.{slug_value}",
            "limit": "1",
        },
    )
    city_id = rows[0]["id"] if rows else None
    if city_id is not None:
        with _SUPABASE_ID_CACHE_LOCK:
            _SUPABASE_CITY_ID_CACHE[slug_value] = city_id
    return city_id


def _supabase_category_id(category_key):
    # Ключи категорий внутри Telegram-бота отличаются от slug
    # категорий в Supabase, поэтому явно сопоставляем их.
    category_slug_map = {
        "realestate": "real-estate",
        "auto": "cars",
        "tech": "electronics",
        "home": "home",
        "kids": "kids",
        "work": "jobs-services",
        "services": "services",
        "pets": "pets",
        "give": "free",
        "search": "wanted",
    }

    category_slug = category_slug_map.get(
        str(category_key).strip().lower(),
        str(category_key).strip().lower(),
    )

    rows = supabase_request(
        "GET",
        "categories",
        params={
            "select": "id,slug",
            "slug": f"eq.{category_slug}",
            "limit": "1",
        },
    )
    return rows[0]["id"] if rows else None


def _supabase_user_id(telegram_id):
    if not telegram_id:
        return None

    telegram_id = int(telegram_id)
    with _SUPABASE_ID_CACHE_LOCK:
        cached_id = _SUPABASE_USER_ID_CACHE.get(telegram_id)
    if cached_id is not None:
        return cached_id

    existing = supabase_request(
        "GET",
        "users",
        params={
            "select": "id,telegram_id",
            "telegram_id": f"eq.{telegram_id}",
            "limit": "1",
        },
    )
    if existing:
        user_id = existing[0]["id"]
        with _SUPABASE_ID_CACHE_LOCK:
            _SUPABASE_USER_ID_CACHE[telegram_id] = user_id
        return user_id

    created = supabase_request(
        "POST",
        "users",
        payload={"telegram_id": telegram_id},
    )
    if created:
        user_id = created[0]["id"]
        with _SUPABASE_ID_CACHE_LOCK:
            _SUPABASE_USER_ID_CACHE[telegram_id] = user_id
        return user_id

    # Race condition / повторная попытка.
    existing = supabase_request(
        "GET",
        "users",
        params={
            "select": "id,telegram_id",
            "telegram_id": f"eq.{telegram_id}",
            "limit": "1",
        },
    )
    user_id = existing[0]["id"] if existing else None
    if user_id is not None:
        with _SUPABASE_ID_CACHE_LOCK:
            _SUPABASE_USER_ID_CACHE[telegram_id] = user_id
    return user_id


def _sync_supabase_user_profile(telegram_user):
    """Sync non-empty public Telegram profile fields for an authenticated user."""
    if not isinstance(telegram_user, dict) or not supabase_enabled():
        return False

    telegram_id = telegram_user.get("id")
    user_id = _supabase_user_id(telegram_id)
    if user_id is None:
        return False

    profile = {}
    for field in ("username", "first_name", "last_name"):
        value = str(telegram_user.get(field) or "").strip()
        if value:
            profile[field] = value.lstrip("@") if field == "username" else value

    if not profile:
        return True

    current = supabase_request(
        "GET",
        "users",
        params={
            "select": "id,username,first_name,last_name",
            "id": f"eq.{user_id}",
            "limit": "1",
        },
    )
    if not current:
        return False

    existing = current[0]
    changed = {
        field: value
        for field, value in profile.items()
        if str(existing.get(field) or "").strip() != value
    }
    if not changed:
        return True

    updated = supabase_request(
        "PATCH",
        "users",
        params={"id": f"eq.{user_id}"},
        payload=changed,
    )
    return updated is not None


def _strip_public_listing_fields(item):
    """Remove private lifecycle fields while retaining the public publication timestamp for cards."""
    for key in ("status", "expires_at", "reminder_sent_at", "channel_message_id"):
        item.pop(key, None)
    item.pop("legacy_id", None)
    return item


def _strip_listing_contact_fields(item):
    """Keep direct contact details out of catalog/favorites payloads; detail view fetches them on demand."""
    for key in ("contact", "phone", "whatsapp", "telegram"):
        item.pop(key, None)
    return item


def _row_to_listing(row):
    metadata = row.get("metadata") or {}
    if not isinstance(metadata, dict):
        metadata = {}

    item = dict(metadata)
    # Internal migration identifier is stored for compatibility, but is not part of the public API.
    item.pop("legacy_id", None)
    item["id"] = row.get("id", item.get("id"))
    # The normalized database title is the canonical generated product/property name.
    # Keep it available to catalog cards even when older metadata has no separate title.
    item["title"] = row.get("title") or item.get("title") or ""
    item["status"] = row.get("status", "published")
    item["published_at"] = row.get("published_at") or row.get("created_at")
    item["expires_at"] = row.get("expires_at")
    item["reminder_sent_at"] = row.get("reminder_sent_at")
    item["channel_message_id"] = row.get("channel_message_id")
    item["channel_post_url"] = row.get("channel_url", "") or ""

    # Данные из нормализованных колонок имеют приоритет.
    if row.get("address"):
        item["district"] = row["address"]
    if row.get("description") is not None:
        item["description"] = row.get("description") or ""
    if row.get("currency"):
        item["currency"] = row["currency"]
    if row.get("price") is not None:
        item["price"] = str(row["price"])

    photos = []
    for photo in row.get("listing_photos", []) or []:
        if photo.get("photo_url"):
            photos.append(photo["photo_url"])
    if photos:
        item["photos"] = photos

    return item


def load_supabase_published_listings():
    global published_listings, next_listing_id

    if not supabase_enabled():
        return False

    # В память загружаем только базовую информацию.
    # Полный каталог теперь запрашивается постранично через
    # load_supabase_catalog_page(), чтобы 10 000+ объявлений
    # не загружались целиком при старте бота.
    rows = supabase_request(
        "GET",
        "listings",
        params={
            "select": "id,status,channel_message_id,channel_url,title,description,currency,price,address,metadata,created_at,published_at",
            "status": "eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "order": "created_at.desc",
            "limit": "1",
        },
    )

    if rows is None:
        return False

    published_listings = [_row_to_listing(row) for row in rows]
    numeric_ids = [
        int(item["id"])
        for item in published_listings
        if str(item.get("id", "")).isdigit()
    ]
    next_listing_id = max(numeric_ids, default=0) + 1
    return True


def _supabase_photo_rows(listing_ids):
    if not listing_ids:
        return []

    values = ",".join(str(int(value)) for value in listing_ids)
    return supabase_request(
        "GET",
        "listing_photos",
        params={
            "select": "listing_id,photo_url,sort_order",
            "listing_id": f"in.({values})",
            "order": "sort_order.asc",
        },
    ) or []


def _attach_catalog_photos(rows):
    photos_by_listing = {}
    for photo in _supabase_photo_rows([row.get("id") for row in rows]):
        listing_id = photo.get("listing_id")
        photo_url = photo.get("photo_url")
        if listing_id and photo_url:
            photos_by_listing.setdefault(listing_id, []).append(photo_url)

    result = []
    for row in rows:
        item = _row_to_listing(row)
        item["photos"] = photos_by_listing.get(row.get("id"), [])
        result.append(item)
    return result


def load_supabase_catalog_page(key, sub, page=0, per_page=20):
    """
    Загружает только текущую страницу каталога из Supabase.
    Никаких 10 000 объявлений и фотографий в память.
    Возвращает (items, has_next).
    """
    if not supabase_enabled():
        return [], False

    page = max(0, int(page))
    per_page = max(1, min(int(per_page), 50))
    offset = page * per_page

    # Обычные категории фильтруются по индексируемому category_id.
    if key != "search":
        category_id = _supabase_category_id(key)
        if not category_id:
            return [], False

        params = {
            "select": "id,status,channel_message_id,channel_url,title,description,currency,price,address,metadata,created_at,published_at",
            "status": "eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "category_id": f"eq.{category_id}",
            "order": "created_at.desc",
            "offset": str(offset),
            "limit": str(per_page + 1),
        }

        if sub != "all":
            params["metadata->>subcategory_key"] = f"eq.{sub}"

        rows = supabase_request("GET", "listings", params=params) or []
        has_next = len(rows) > per_page
        rows = rows[:per_page]
        return _attach_catalog_photos(rows), has_next

    # Раздел "Ищу" хранится отдельной категорией.
    # Для конкретной тематики объединяем обычную категорию и wanted-объявления.
    # Для первой версии достаточно ограниченных страниц: запрос никогда не
    # вытаскивает весь каталог.
    if sub == "all":
        rows = supabase_request(
            "GET",
            "listings",
            params={
                "select": "id,status,channel_message_id,channel_url,title,description,currency,price,address,metadata,created_at,published_at",
                "status": "eq.published",
                "expires_at": f"gt.{_utc_now_iso()}",
                "order": "created_at.desc",
                "offset": str(offset),
                "limit": str(per_page + 1),
            },
        ) or []
        has_next = len(rows) > per_page
        rows = rows[:per_page]
        return _attach_catalog_photos(rows), has_next

    normal_category_id = _supabase_category_id(sub)
    wanted_category_id = _supabase_category_id("search")
    if not normal_category_id and not wanted_category_id:
        return [], False

    candidates = []
    wanted_needed = offset + per_page + 1

    if normal_category_id:
        candidates.extend(supabase_request(
            "GET",
            "listings",
            params={
                "select": "id,status,channel_message_id,channel_url,title,description,currency,price,address,metadata,created_at,published_at",
                "status": "eq.published",
                "expires_at": f"gt.{_utc_now_iso()}",
                "category_id": f"eq.{normal_category_id}",
                "order": "created_at.desc",
                "offset": "0",
                "limit": str(wanted_needed),
            },
        ) or [])

    if wanted_category_id:
        candidates.extend(supabase_request(
            "GET",
            "listings",
            params={
                "select": "id,status,channel_message_id,channel_url,title,description,currency,price,address,metadata,created_at,published_at",
                "status": "eq.published",
                "expires_at": f"gt.{_utc_now_iso()}",
                "category_id": f"eq.{wanted_category_id}",
                "metadata->>subcategory_key": f"eq.{sub}",
                "order": "created_at.desc",
                "offset": "0",
                "limit": str(wanted_needed),
            },
        ) or [])

    # Объединяем и сортируем только ограниченный набор кандидатов.
    unique = {}
    for row in candidates:
        unique[str(row.get("id"))] = row

    rows = sorted(
        unique.values(),
        key=lambda row: row.get("created_at", ""),
        reverse=True,
    )
    page_rows = rows[offset:offset + per_page]
    has_next = len(rows) > offset + per_page
    return _attach_catalog_photos(page_rows), has_next

def save_listing_to_supabase(data, publish_result, user_chat_id=None):
    """Создаёт объявление в Supabase; любая ошибка означает отказ публикации в каталоге."""

    global LAST_SUPABASE_ERROR
    LAST_SUPABASE_ERROR = ""
    if not supabase_enabled():
        LAST_SUPABASE_ERROR = "Supabase is not configured"
        print("SUPABASE: publication blocked — Supabase is not configured")
        return None

    city_slug = _canonical_city_slug(data.get("city_slug") or DEFAULT_CITY_SLUG)
    city_id = _supabase_city_id(city_slug)
    category_id = _supabase_category_id(data.get("category_key", ""))

    if not city_id:
        LAST_SUPABASE_ERROR = f"City is not registered in Supabase: {city_slug}"
        print("SUPABASE: publication blocked — city not found:", city_slug)
        return None
    if not category_id:
        LAST_SUPABASE_ERROR = f"Category is not registered in Supabase: {data.get('category_key')}"
        print("SUPABASE: publication blocked — category not found:", data.get("category_key"))
        return None

    user_id = _supabase_user_id(user_chat_id)

    result = publish_result.get("result") if isinstance(publish_result, dict) else None
    message_id = None
    if isinstance(result, list) and result:
        message_id = result[0].get("message_id")
    elif isinstance(result, dict):
        message_id = result.get("message_id")

    channel_url = ""
    if CHANNEL_USERNAME.startswith("@") and message_id:
        channel_url = f"https://t.me/{CHANNEL_USERNAME[1:]}/{message_id}"

    metadata = dict(data)
    metadata.pop("_telegram_id", None)
    metadata["telegram_username"] = str(data.get("telegram_username") or "").strip().lstrip("@")
    metadata["telegram"] = (
        f"https://t.me/{metadata['telegram_username']}"
        if metadata["telegram_username"] else ""
    )
    metadata["legacy_id"] = data.get("id")
    # address/district remains the exact street or landmark; district_key is a separate stable filter key.
    metadata["district_key"] = str(data.get("district_key") or "").strip().lower() or None

    payload = {
        "user_id": user_id,
        "city_id": city_id,
        "category_id": category_id,
        "title": listing_title(data),
        "description": data.get("description", "") or "",
        "price": _price_number(data.get("price")),
        "currency": data.get("currency", "") or "USD",
        "phone": data.get("contact", "") or "",
        # public.listings.telegram is BOOLEAN; the username/link belongs in metadata.
        "telegram": bool(str(data.get("telegram_username") or "").strip().lstrip("@")),
        "address": data.get("district", "") or "",
        "status": "published",
        "published_at": _utc_now_iso(),
        "expires_at": (datetime.now(timezone.utc) + timedelta(days=10)).isoformat(),
        "reminder_sent_at": None,
        "channel_message_id": message_id,
        "channel_url": channel_url,
        "metadata": metadata,
    }

    created = supabase_request("POST", "listings", payload=payload)
    if not created:
        LAST_SUPABASE_ERROR = LAST_SUPABASE_ERROR or "Supabase did not return the created listing row"
        print("SUPABASE: publication blocked — listing insert failed:", LAST_SUPABASE_ERROR)
        return None

    row = created[0]
    listing_id = row.get("id")

    photos = [
        {
            "listing_id": listing_id,
            "photo_url": str(photo),
            "sort_order": index,
        }
        for index, photo in enumerate(data.get("photos", []))
        if photo
    ]

    if photos:
        inserted_photos = supabase_request(
            "POST",
            "listing_photos",
            payload=photos,
        )
        if not inserted_photos:
            LAST_SUPABASE_ERROR = LAST_SUPABASE_ERROR or "Supabase did not save listing photos"
            print("SUPABASE: photo insert failed; rolling back listing", listing_id, LAST_SUPABASE_ERROR)
            supabase_request("DELETE", "listings", params={"id": f"eq.{listing_id}"})
            return None

    return _row_to_listing({**row, "listing_photos": photos})


def register_published_listing(data, publish_result, user_chat_id=None):
    """Сохраняет публикацию в Supabase. Локальный JSON не считается успехом каталога."""
    global published_listings

    supabase_item = save_listing_to_supabase(
        data,
        publish_result,
        user_chat_id=user_chat_id,
    )
    if not supabase_item:
        print("SUPABASE: listing was NOT registered; moderation request must remain pending")
        return None

    # Обновляем память из БД, чтобы каталог сразу видел новое объявление.
    if not load_supabase_published_listings():
        published_listings.insert(0, supabase_item)
    return supabase_item


def load_published_listings():
    """Загрузка каталога. Supabase — основной источник, JSON — fallback."""
    load_local_published_listings()
    if supabase_enabled():
        if load_supabase_published_listings():
            print("LISTINGS STORAGE: Supabase")
        else:
            print("LISTINGS STORAGE: local fallback")
    else:
        print("LISTINGS STORAGE: local listings.json (Supabase env not set)")


