def category_fields(data):
    """Return fields appropriate to the selected category/subcategory."""
    category_key = str((data or {}).get("category_key", ""))
    subcategory_key = str((data or {}).get("subcategory_key", ""))
    if category_key == "auto" and subcategory_key in {"cars", "suv"}:
        return [
            ("make_model", "🚗 Марка и модель"),
            ("year", "📅 Год выпуска"),
            ("mileage", "🛣 Пробег"),
            ("color", "🎨 Цвет автомобиля"),
            ("drivetrain", "⚙️ Привод"),
        ]
    if category_key == "auto" and subcategory_key not in {"cars", "suv"}:
        return CATEGORIES.get(category_key, {}).get("fields", [])
    if category_key == "realestate":
        fields = list(CATEGORIES.get(category_key, {}).get("fields", []))
        if subcategory_key in {"land", "garage"}:
            fields = [field for field in fields if field[0] not in {"rooms", "floor"}]
        elif subcategory_key == "room":
            fields = [field for field in fields if field[0] != "rooms"]
        return fields
    if category_key == "pets":
        if subcategory_key in {"dogs", "cats", "other_animals", "adoption", "lost_found"}:
            return [("age", "🐾 Возраст"), ("breed", "🐾 Порода (если известна)"), ("gender", "🐾 Пол (если известен)")]
        if subcategory_key == "supplies":
            return [("condition", "✨ Состояние товара")]
        if subcategory_key == "services":
            return [("service", "✂️ Какая услуга"), ("experience", "⭐ Опыт")]
        # The general "other" category should not ask pet owners about product condition.
        return []
    return CATEGORIES.get(category_key, {}).get("fields", [])


