AUTO_DRIVETRAIN_OPTIONS = [
    "Передний (FWD)", "Задний (RWD)", "Полный (AWD/4WD)", "Другой / не знаю",
]


def auto_attribute_options(kind):
    if kind == "color":
        return AUTO_COLOR_OPTIONS
    if kind == "drivetrain":
        return AUTO_DRIVETRAIN_OPTIONS
    return []


def send_auto_attribute_picker(chat_id, index, kind, page=0):
    options = auto_attribute_options(kind)
    is_edit = str(states[chat_id].get("step", "")).startswith("edit_detail_")
    states[chat_id]["step"] = f"edit_detail_{index}" if is_edit else f"detail_{index}"
    states[chat_id]["auto_picker"] = {"kind": kind, "index": index, "page": page, "is_edit": is_edit}
    title = "цвет" if kind == "color" else "привод"
    send(chat_id, f"<b>🚗 Выберите {title} автомобиля</b>", auto_choice_keyboard(kind, options, page))


def auto_choice_keyboard(kind, options, page=0):
    """Compact paginated Telegram inline selector for auto make/model."""
    total_pages = max(1, (len(options) + AUTO_PICK_PAGE_SIZE - 1) // AUTO_PICK_PAGE_SIZE)
    page = max(0, min(int(page), total_pages - 1))
    start = page * AUTO_PICK_PAGE_SIZE
    visible = options[start:start + AUTO_PICK_PAGE_SIZE]
    rows = [[{"text": value, "callback_data": f"autopick_{kind}_{start+i}"}]
            for i, value in enumerate(visible)]
    nav = []
    if page > 0:
        nav.append({"text": "⬅️ Назад", "callback_data": f"autopage_{kind}_{page-1}"})
    nav.append({"text": f"{page+1}/{total_pages}", "callback_data": "autopage_noop"})
    if page + 1 < total_pages:
        nav.append({"text": "Далее ➡️", "callback_data": f"autopage_{kind}_{page+1}"})
    if nav:
        rows.append(nav)
    return rows


def send_auto_make_picker(chat_id, index, page=0):
    send_listing_picker(chat_id, "<b>🚗 Выберите марку автомобиля</b>", "make", index)


def send_auto_model_picker(chat_id, index, make, page=0):
    options = auto_model_options(make)
    if not options:
        details = states[chat_id]["data"].setdefault("details", {})
        details["make_model"] = make
        details["make"] = make
        details["model"] = ""
        picker = states[chat_id].get("listing_picker") or {}
        states[chat_id].pop("listing_picker", None)
        if picker.get("is_edit"):
            preview(chat_id)
        else:
            ask_detail(chat_id, index + 1)
        return
    send_listing_picker(chat_id, f"<b>{esc(make)}</b>\nВыберите модель автомобиля", "model", index, make)


