def make_title(
    data
):

    category = data[
        "category_key"
    ]

    details = data[
        "details"
    ]

    # Заголовок — только суть объявления.
    # Тип действия (Сдам / Сниму / Продам / Куплю / Ищу)
    # уже показывается в верхней строке карточки, поэтому
    # повторять его здесь не нужно.

    if category == "realestate":

        rooms = details.get(
            "rooms",
            ""
        )

        subcategory = data.get(
            "subcategory_key",
            ""
        )

        property_names = {
            "apartment": "квартира",
            "house": "дом",
            "room": "комната",
            "commercial": "коммерческое помещение",
            "land": "земельный участок",
            "garage": "гараж / парковка",
        }

        property_name = property_names.get(
            subcategory,
            "объект недвижимости"
        )

        if subcategory == "apartment" and rooms:
            return f"{rooms}-комнатная квартира"

        if subcategory == "room" and rooms:
            return f"{rooms}-комнатная комната"

        return property_name

    if category == "auto":

        model = (
            details.get(
                "make_model",
                ""
            )
            or "автомобиль"
        )

        year = details.get(
            "year",
            ""
        )

        title = model

        if year:
            title += f" · {year}"

        return title

    if category == "tech":

        return (
            details.get(
                "brand_model",
                ""
            )
            or "Техника"
        )

    if category == "work":

        return (
            details.get(
                "service",
                ""
            )
            or "Работа / услуга в Батуми"
        )

    if category == "search":

        return (
            details.get(
                "requirements",
                ""
            )
            or ""
        )

    # Для «Отдам» отдельный заголовок не нужен:
    # тип и подкатегория уже показаны выше.
    if category == "give":
        return ""

    return ""


