def _is_admin_telegram_user(user):
    try:
        return bool(user and str(user.get("id", "")) in ADMIN_TELEGRAM_IDS)
    except Exception:
        return False


def _track_mm_event(event_type, telegram_id, listing_id=None):
    """Best-effort analytics: never block regular Mini App requests on analytics errors."""
    if not supabase_enabled() or not telegram_id or event_type not in {"app_open", "listing_view"}:
        return
    payload = {"event_type": event_type, "telegram_id": int(telegram_id)}
    if listing_id is not None:
        try:
            payload["listing_id"] = int(listing_id)
        except (TypeError, ValueError):
            return
    try:
        supabase_request("POST", "mm_analytics_events", payload=payload)
    except Exception as error:
        print("MADLOBA ANALYTICS ERROR:", repr(error))


def _admin_stats_payload(period_days=7):
    try:
        period_days = int(period_days)
    except (TypeError, ValueError):
        period_days = 7
    if period_days not in (7, 30, 90):
        period_days = 7
    # Read only existing records; analytics tables are additive and optional during rollout.
    stats = {
        "users_total": 0, "listings_total": 0, "listings_active": 0,
        "listings_pending": 0, "listings_other": 0,
        "opens_today": 0, "opens_7d": 0, "unique_visitors_7d": 0,
        "listing_views_today": 0, "listing_views_7d": 0,
        "period_days": period_days, "opens_period": 0, "unique_visitors_period": 0,
        "listing_views_period": 0, "activity_by_day": [], "top_listings": [],
        "orders_total": 0, "orders_pending": 0, "orders_paid": 0,
        "analytics_available": False, "orders_available": False,
    }
    if not supabase_enabled():
        return stats
    # Prefer exact database-side counts: never transfer the full users/listings
    # tables just to display dashboard totals. Keep the old bounded reads only as
    # a compatibility fallback if this PostgREST deployment lacks HEAD counts.
    users_count = _supabase_exact_count("users")
    if users_count is not None:
        stats["users_total"] = users_count
    else:
        users = _supabase_fetch_all_bounded("users", params={"select":"id"})
        if isinstance(users, list):
            stats["users_total"] = len(users)

    listings_count = _supabase_exact_count("listings")
    active_count = None
    pending_count = None
    if listings_count is not None:
        active_count = _supabase_exact_count("listings", {"status":"in.(published,active)"})
        if active_count is not None:
            pending_count = _supabase_exact_count(
                "listings", {"status":"in.(pending,pending_moderation,moderation,review)"}
            )
    if listings_count is not None and active_count is not None and pending_count is not None:
        stats["listings_total"] = listings_count
        stats["listings_active"] = active_count
        stats["listings_pending"] = pending_count
        stats["listings_other"] = max(0, listings_count - active_count - pending_count)
    else:
        listings = _supabase_fetch_all_bounded("listings", params={"select":"id,status"})
        if isinstance(listings, list):
            stats["listings_total"] = len(listings)
            for row in listings:
                status = str(row.get("status", "")).lower()
                if status in {"published", "active"}:
                    stats["listings_active"] += 1
                elif status in {"pending", "pending_moderation", "moderation", "review"}:
                    stats["listings_pending"] += 1
                else:
                    stats["listings_other"] += 1
    from datetime import datetime, timezone, timedelta
    now = datetime.now(timezone.utc)
    today = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
    period_start = (now - timedelta(days=period_days - 1)).replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
    # Prefer database-side aggregation. Fall back to the previous implementation
    # only if the RPC is unavailable, so the admin panel remains usable during rollout.
    analytics_result = supabase_request(
        "POST", "rpc/mm_admin_analytics_stats",
        payload={"p_period_days": period_days},
    )
    if isinstance(analytics_result, list) and analytics_result and isinstance(analytics_result[0], dict):
        analytics_result = analytics_result[0]
    if isinstance(analytics_result, dict) and analytics_result.get("analytics_available"):
        stats["analytics_available"] = True
        for key in (
            "opens_today", "opens_7d", "unique_visitors_7d",
            "listing_views_today", "listing_views_7d", "period_days",
            "opens_period", "unique_visitors_period", "listing_views_period",
            "activity_by_day", "top_listings",
        ):
            if key in analytics_result:
                stats[key] = analytics_result[key]
    else:
        # Compatibility fallback for deployments where the SQL function has not
        # yet been applied or is temporarily unavailable.
        events = _supabase_fetch_all_bounded("mm_analytics_events", params={
            "select":"id,event_type,telegram_id,listing_id,created_at",
            "created_at":f"gte.{period_start}",
        })
        if isinstance(events, list):
            stats["analytics_available"] = True
            visitors = set()
            top_counts = {}
            daily = {}
            for offset in range(period_days - 1, -1, -1):
                day = (now - timedelta(days=offset)).date().isoformat()
                daily[day] = {"date": day, "opens": 0, "views": 0}
            for event in events:
                created = str(event.get("created_at", ""))
                kind = event.get("event_type")
                try:
                    event_day = datetime.fromisoformat(created.replace("Z", "+00:00")).astimezone(timezone.utc).date().isoformat()
                except (TypeError, ValueError):
                    event_day = ""
                if kind == "app_open":
                    stats["opens_period"] += 1
                    if event.get("telegram_id") is not None:
                        visitors.add(str(event.get("telegram_id")))
                    if created >= today:
                        stats["opens_today"] += 1
                    if event_day in daily:
                        daily[event_day]["opens"] += 1
                elif kind == "listing_view":
                    stats["listing_views_period"] += 1
                    listing_id = event.get("listing_id")
                    if listing_id is not None:
                        key = str(listing_id)
                        top_counts[key] = top_counts.get(key, 0) + 1
                    if created >= today:
                        stats["listing_views_today"] += 1
                    if event_day in daily:
                        daily[event_day]["views"] += 1
            stats["opens_7d"] = stats["opens_period"]
            stats["unique_visitors_period"] = len(visitors)
            stats["unique_visitors_7d"] = len(visitors)
            stats["listing_views_7d"] = stats["listing_views_period"]
            stats["activity_by_day"] = list(daily.values())
            if top_counts:
                top_ids = sorted(top_counts, key=top_counts.get, reverse=True)[:10]
                try:
                    top_rows = supabase_request("GET", "listings", params={
                        "select":"id,title,status,price,currency", "id":f"in.({','.join(top_ids)})", "limit":"10"
                    })
                    if isinstance(top_rows, list):
                        by_id = {str(row.get("id")): row for row in top_rows}
                        stats["top_listings"] = [dict(by_id.get(key, {"id": key, "title": "Объявление"}), views=top_counts[key]) for key in top_ids]
                except Exception as error:
                    print("MADLOBA TOP LISTINGS ERROR:", repr(error))
    orders_count = _supabase_exact_count("mm_orders")
    pending_orders_count = None
    paid_orders_count = None
    if orders_count is not None:
        pending_orders_count = _supabase_exact_count("mm_orders", {"status":"eq.pending_payment"})
        if pending_orders_count is not None:
            paid_orders_count = _supabase_exact_count("mm_orders", {"status":"eq.paid"})
    if orders_count is not None and pending_orders_count is not None and paid_orders_count is not None:
        stats["orders_available"] = True
        stats["orders_total"] = orders_count
        stats["orders_pending"] = pending_orders_count
        stats["orders_paid"] = paid_orders_count
    else:
        # mm_orders is optional until monetization is enabled; retain the old
        # behavior if exact counts are not supported or the table is absent.
        orders = _supabase_fetch_all_bounded("mm_orders", params={"select":"id,status"})
        if isinstance(orders, list):
            stats["orders_available"] = True
            stats["orders_total"] = len(orders)
            stats["orders_pending"] = sum(1 for x in orders if x.get("status") == "pending_payment")
            stats["orders_paid"] = sum(1 for x in orders if x.get("status") == "paid")
    return stats


