@app.get("/api/admin/stats")
def mini_app_admin_stats():
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    try:
        days = int(request.args.get("days", "7"))
    except (TypeError, ValueError):
        days = 7
    if days not in (7, 30, 90):
        days = 7
    return jsonify(_admin_stats_payload(days))


@app.get("/api/admin/data")
def mini_app_admin_data():
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503

    kind = (request.args.get("kind") or "").strip().lower()
    if kind == "user":
        user_id = (request.args.get("id") or "").strip()
        if not user_id.isdigit():
            return jsonify({"error":"invalid_id"}), 400
        rows = supabase_request("GET", "users", params={
            "select":"*", "id":f"eq.{user_id}", "limit":"1"
        })
        if not isinstance(rows, list) or not rows:
            return jsonify({"error":"user_not_found"}), 404
        user_row = rows[0]
        listings = supabase_request("GET", "listings", params={
            "select":"id,title,status,price,currency,created_at", "user_id":f"eq.{user_id}",
            "order":"created_at.desc", "limit":"100"
        })
        return jsonify({"item":user_row, "listings":listings if isinstance(listings,list) else []})

    if kind == "listing":
        listing_id = (request.args.get("id") or "").strip()
        if not listing_id.isdigit():
            return jsonify({"error":"invalid_id"}), 400
        rows = supabase_request("GET", "listings", params={
            "select":"*", "id":f"eq.{listing_id}", "limit":"1"
        })
        if not isinstance(rows, list) or not rows:
            return jsonify({"error":"listing_not_found"}), 404
        item = dict(rows[0])
        # Prefer the event log for the admin-facing view count. This does not
        # mutate listings or change the publication flow; analytics stays optional.
        try:
            exact_views = _supabase_exact_count("mm_analytics_events", {
                "event_type":"eq.listing_view", "listing_id":f"eq.{listing_id}"
            })
            if exact_views is not None:
                item["views_count"] = exact_views
            else:
                view_events = supabase_request("GET", "mm_analytics_events", params={
                    "select":"id", "event_type":"eq.listing_view",
                    "listing_id":f"eq.{listing_id}", "limit":"100000"
                })
                if isinstance(view_events, list):
                    item["views_count"] = len(view_events)
        except Exception as error:
            print("MADLOBA LISTING VIEW COUNT ERROR:", repr(error))
        return jsonify({"item":item})

    if kind == "reports":
        rows = supabase_request("GET", "mm_listing_reports", params={
            "select":"id,listing_id,listing_title,reporter_user_id,reason,details,status,admin_note,created_at,updated_at",
            "order":"created_at.desc", "limit":"100"
        })
        if rows is None:
            return jsonify({"error":"reports_unavailable"}), 503
        return jsonify({"items": rows})

    if kind in {"users", "listings"}:
        # Admin lists are always server-paginated. The dashboard preview requests
        # five rows; the full browser requests at most twenty rows per page.
        try:
            page = max(0, int(request.args.get("page", "0")))
            limit = int(request.args.get("limit", request.args.get("per_page", "5")))
        except (TypeError, ValueError):
            return jsonify({"error":"invalid_pagination"}), 400
        limit = max(1, min(limit, 20))
        offset = page * limit
        query = str(request.args.get("q") or "").strip()
        # Restrict search syntax so user input cannot alter PostgREST filter grammar.
        query = re.sub(r"[^\w\s@.+-]", "", query, flags=re.UNICODE)[:80].strip()
        filters = {}
        if kind == "listings":
            # Main admin browser is an operational queue: current publications and moderation only.
            filters["status"] = "in.(published,pending,pending_moderation,moderation,review)"
        if query:
            safe = query.replace("\\", "")
            if kind == "users":
                terms = [f"username.ilike.*{safe}*", f"first_name.ilike.*{safe}*", f"last_name.ilike.*{safe}*"]
                if safe.isdigit():
                    terms.extend([f"id.eq.{safe}", f"telegram_id.eq.{safe}"])
                filters["or"] = "(" + ",".join(terms) + ")"
            else:
                terms = [f"title.ilike.*{safe}*", f"address.ilike.*{safe}*"]
                if safe.isdigit():
                    terms.append(f"id.eq.{safe}")
                filters["or"] = "(" + ",".join(terms) + ")"

        table = "users" if kind == "users" else "listings"
        select = "id,telegram_id,username,first_name,last_name,created_at" if kind == "users" else "id,user_id,title,status,price,currency,address,created_at"
        count = _supabase_exact_count(table, filters)
        params = {"select":select, "order":"id.desc" if kind == "users" else "created_at.desc,id.desc",
                  "limit":str(limit), "offset":str(offset)}
        params.update(filters)
        rows = supabase_request("GET", table, params=params)
        if rows is None:
            return jsonify({"error":f"{kind}_unavailable"}), 503

        if kind == "users":
            return jsonify({"items":rows, "total":count, "page":page, "per_page":limit})

        user_ids = {str(row.get("user_id")) for row in rows if row.get("user_id")}
        owner_map = {}
        if user_ids:
            owners = supabase_request("GET", "users", params={
                "select":"id,telegram_id", "id":f"in.({','.join(user_ids)})", "limit":"100"
            })
            if isinstance(owners, list):
                owner_map = {str(owner.get("id")): owner.get("telegram_id") for owner in owners}
        items = []
        for row in rows:
            item = dict(row)
            item["telegram_id"] = owner_map.get(str(row.get("user_id")), "")
            items.append(item)
        return jsonify({"items":items, "total":count, "page":page, "per_page":limit})

    return jsonify({"error":"invalid_kind"}), 400


@app.post("/api/listing/<int:listing_id>/report")
def mini_app_submit_listing_report(listing_id):
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"ok":False,"error":"invalid_init_data"}), 401
    if not supabase_enabled():
        return jsonify({"ok":False,"error":"db_unavailable"}), 503
    payload = request.get_json(silent=True) or {}
    reason = str(payload.get("reason") or "").strip().lower()
    allowed_reasons = {"scam", "false_information", "spam", "prohibited_item", "other"}
    if reason not in allowed_reasons:
        return jsonify({"ok":False,"error":"invalid_reason"}), 400
    details = str(payload.get("details") or "").strip()
    if len(details) > 1000:
        return jsonify({"ok":False,"error":"details_too_long"}), 400
    listing_rows = supabase_request("GET", "listings", params={
        "select":"id,user_id,title,status",
        "id":f"eq.{listing_id}", "status":"eq.published", "limit":"1"
    })
    if not isinstance(listing_rows, list) or not listing_rows:
        return jsonify({"ok":False,"error":"listing_not_found"}), 404
    reporter_id = _supabase_user_id(user.get("id"))
    if not reporter_id:
        return jsonify({"ok":False,"error":"user_sync_failed"}), 503
    if str(listing_rows[0].get("user_id") or "") == str(reporter_id):
        return jsonify({"ok":False,"error":"cannot_report_own_listing"}), 400
    existing = supabase_request("GET", "mm_listing_reports", params={
        "select":"id", "listing_id":f"eq.{listing_id}",
        "reporter_user_id":f"eq.{reporter_id}", "status":"in.(new,reviewing)", "limit":"1"
    })
    if isinstance(existing, list) and existing:
        return jsonify({"ok":False,"error":"duplicate_active_report"}), 409
    inserted = supabase_request("POST", "mm_listing_reports", payload={
        "listing_id":listing_id,
        "listing_title":str(listing_rows[0].get("title") or "Объявление")[:500],
        "reporter_user_id":reporter_id,
        "reason":reason,
        "details":details or None,
        "status":"new"
    })
    if not isinstance(inserted, list) or not inserted:
        print("MADLOBA REPORT INSERT ERROR:", str(LAST_SUPABASE_ERROR)[:500])
        if "duplicate key" in str(LAST_SUPABASE_ERROR).lower():
            return jsonify({"ok":False,"error":"duplicate_active_report"}), 409
        return jsonify({
            "ok": False,
            "error": "report_save_failed",
            "detail": str(LAST_SUPABASE_ERROR or "Supabase returned no inserted row")[:500],
        }), 503
    return jsonify({"ok":True,"report_id":inserted[0].get("id")})


@app.post("/api/admin/report/<int:report_id>/action")
def mini_app_admin_report_action(report_id):
    admin = _mini_app_authenticated_user()
    if not admin:
        return jsonify({"ok":False,"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(admin):
        return jsonify({"ok":False,"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"ok":False,"error":"db_unavailable"}), 503
    payload = request.get_json(silent=True) or {}
    action = str(payload.get("action") or "").strip().lower()
    reports = supabase_request("GET", "mm_listing_reports", params={
        "select":"id,listing_id,status", "id":f"eq.{report_id}", "limit":"1"
    })
    if not isinstance(reports, list) or not reports:
        return jsonify({"ok":False,"error":"report_not_found"}), 404
    report = reports[0]
    if action == "review":
        updated = supabase_request("PATCH", "mm_listing_reports", params={"id":f"eq.{report_id}"}, payload={"status":"reviewing","updated_at":_utc_now_iso()})
    elif action == "dismiss":
        updated = supabase_request("PATCH", "mm_listing_reports", params={"id":f"eq.{report_id}"}, payload={"status":"dismissed","updated_at":_utc_now_iso()})
    elif action == "hide":
        listing_id = report.get("listing_id")
        if not listing_id:
            return jsonify({"ok":False,"error":"listing_already_missing"}), 409
        hidden = supabase_request("PATCH", "listings", params={"id":f"eq.{listing_id}","status":"eq.published"}, payload={"status":"archived","updated_at":_utc_now_iso()})
        if not isinstance(hidden, list) or not hidden:
            return jsonify({"ok":False,"error":"listing_hide_failed"}), 503
        updated = supabase_request("PATCH", "mm_listing_reports", params={"id":f"eq.{report_id}"}, payload={"status":"resolved","updated_at":_utc_now_iso()})
    else:
        return jsonify({"ok":False,"error":"invalid_action"}), 400
    if not isinstance(updated, list) or not updated:
        return jsonify({"ok":False,"error":"report_update_failed"}), 503
    return jsonify({"ok":True,"action":action})


