@app.post("/api/support")
def mini_app_support():
    """Forward a Mini App feedback message to configured Telegram administrators."""
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"ok": False, "error": "invalid_init_data"}), 401

    payload = request.get_json(silent=True) or {}
    message = str(payload.get("message") or "").strip()
    topic_key = str(payload.get("topic") or "other").strip().lower()
    topic_labels = {
        "question": "Вопрос", "listing": "Проблема с объявлением",
        "bug": "Ошибка в приложении", "idea": "Предложение", "other": "Другое",
    }
    if not message:
        return jsonify({"ok": False, "error": "empty_message"}), 400
    if len(message) > 2000:
        return jsonify({"ok": False, "error": "message_too_long"}), 400

    admin_ids = set(ADMIN_TELEGRAM_IDS)
    if str(ADMIN_CHAT_ID).strip().isdigit():
        admin_ids.add(str(ADMIN_CHAT_ID).strip())
    if not admin_ids:
        return jsonify({"ok": False, "error": "support_not_configured"}), 503

    user_id = str(user.get("id") or "")
    full_name = " ".join(str(user.get(key) or "").strip() for key in ("first_name", "last_name")).strip()
    username = str(user.get("username") or "").strip()
    city_key = str(payload.get("city") or "batumi").lower()
    city_label = {"batumi": "Batumi", "tbilisi": "Tbilisi"}.get(city_key, "Не указан")
    topic = topic_labels.get(topic_key, topic_labels["other"])
    header = (
        "📩 <b>Обращение из MADLOBA MARKET</b>\n\n"
        f"<b>Тема:</b> {html.escape(topic)}\n"
        f"<b>Пользователь:</b> {html.escape(full_name or 'Telegram пользователь')}"
        + (f" (@{html.escape(username)})" if username else "") + "\n"
        f"<b>Telegram ID:</b> <code>{html.escape(user_id)}</code>\n"
        f"<b>Город:</b> {html.escape(city_label)}\n\n"
        f"<b>Сообщение:</b>\n{html.escape(message)}"
    )
    delivered = 0
    for admin_id in admin_ids:
        notification = {"chat_id": admin_id, "text": header, "parse_mode": "HTML", "disable_web_page_preview": True}
        if user_id.isdigit():
            notification["reply_markup"] = {"inline_keyboard": [[{"text": "💬 Ответить", "callback_data": f"support_reply_{user_id}"}]]}
        result = api("sendMessage", notification)
        if isinstance(result, dict) and result.get("ok"):
            delivered += 1
        else:
            print("MADLOBA SUPPORT DELIVERY ERROR:", admin_id, str(result)[:300])
    if not delivered:
        return jsonify({"ok": False, "error": "delivery_failed"}), 502
    return jsonify({"ok": True})


def _mini_app_owned_row(listing_id):
    """Возвращает объявление, если оно принадлежит текущему Telegram-пользователю."""
    if not supabase_enabled():
        return None, None, None
    user = _mini_app_authenticated_user()
    if not user:
        return None, None, None
    user_id = _supabase_user_id(user.get("id"))
    if not user_id:
        return None, user, None
    rows = supabase_request(
        "GET",
        "listings",
        params={
            "select":"id,user_id,title,description,price,currency,address,metadata,channel_url,channel_message_id,created_at,published_at,expires_at,reminder_sent_at,category_id,city_id,status,phone,whatsapp,telegram",
            "id":f"eq.{int(listing_id)}",
            "user_id":f"eq.{user_id}",
            "limit":"1",
        },
    )
    return (rows[0] if rows else None), user, user_id


def _delete_listing_channel_messages(row):
    """Удаляет связанные сообщения из канала; возвращает False, если удаление надо повторить."""
    ids = []
    metadata = row.get("metadata") or {}
    if isinstance(metadata, dict):
        raw = metadata.get("channel_message_ids") or []
        if isinstance(raw, list):
            ids.extend(raw)
    if row.get("channel_message_id"):
        ids.append(row.get("channel_message_id"))
    seen = set()
    normalized_ids = []
    for message_id in ids:
        try:
            message_id = int(message_id)
        except (TypeError, ValueError):
            continue
        if message_id not in seen:
            seen.add(message_id)
            normalized_ids.append(message_id)
    if not normalized_ids:
        return True
    if not CHANNEL_USERNAME:
        print("LISTING LIFECYCLE: channel username missing; cannot delete posts")
        return False
    all_ok = True
    for message_id in normalized_ids:
        result = api("deleteMessage", {"chat_id": CHANNEL_USERNAME, "message_id": message_id})
        if isinstance(result, dict) and result.get("ok"):
            continue
        description = str(result.get("description", "")).lower() if isinstance(result, dict) else ""
        # Already-deleted messages are safe to treat as complete.
        if "message to delete not found" in description or "message identifier is not specified" in description:
            continue
        all_ok = False
        print("LISTING LIFECYCLE: Telegram delete failed", message_id, description[:200])
    return all_ok


def _sync_edited_listing_to_channel(row, data):
    """Обновляет текст опубликованного объявления в Telegram, когда это возможно."""
    if not CHANNEL_USERNAME or not row.get("channel_message_id"):
        return
    try:
        text_value = build_listing(data)
        photos = data.get("photos") or []
        if photos:
            api("editMessageCaption", {
                "chat_id": CHANNEL_USERNAME,
                "message_id": row.get("channel_message_id"),
                "caption": text_value,
                "parse_mode": "HTML",
            })
        else:
            api("editMessageText", {
                "chat_id": CHANNEL_USERNAME,
                "message_id": row.get("channel_message_id"),
                "text": text_value,
                "parse_mode": "HTML",
            })
    except Exception as error:
        print("MINI APP CHANNEL SYNC ERROR:", repr(error))


@app.get("/api/my-listing/<int:listing_id>")
def mini_app_my_listing(listing_id):
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not row:
        return jsonify({"error":"not_found"}), 404
    item = _attach_catalog_photos([row])[0]
    item["title"] = row.get("title") or item.get("title") or listing_title(item)
    item["description"] = row.get("description") or item.get("description") or ""
    item["price"] = str(row.get("price")) if row.get("price") is not None else item.get("price", "")
    item["currency"] = row.get("currency") or item.get("currency", "")
    item["address"] = row.get("address") or item.get("district", "")
    row_metadata_for_district = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
    item["district_key"] = str(row_metadata_for_district.get("district_key") or "")
    item["phone"] = row.get("phone") or ""
    # WhatsApp/Telegram в Supabase могут быть boolean-полями.
    # Для Mini App берём пользовательские контакты из metadata,
    # где они хранятся как строки.
    row_metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
    item["whatsapp"] = row_metadata.get("whatsapp", "")
    item["telegram"] = row_metadata.get("telegram", "")
    item["status"] = row.get("status") or "draft"
    item["category_name"] = item.get("category") or "Объявление"
    return jsonify(item)


@app.patch("/api/my-listing/<int:listing_id>")
def mini_app_update_listing(listing_id):
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not row:
        return jsonify({"error":"not_found"}), 404
    payload = request.get_json(silent=True) or {}
    description = str(payload.get("description", "")).strip()[:5000]
    address = str(payload.get("address", "")).strip()[:300]
    phone = str(payload.get("phone", "")).strip()[:80]
    whatsapp = str(payload.get("whatsapp", "")).strip()[:80]
    telegram = str(payload.get("telegram", "")).strip()[:80]
    currency = str(payload.get("currency", row.get("currency") or "USD")).upper().strip()
    if currency not in {"USD", "GEL", "EUR"}:
        return jsonify({"error":"invalid_currency"}), 400
    raw_price = str(payload.get("price", "")).strip().replace(",", ".")
    price = None
    if raw_price:
        try:
            price = float(raw_price)
        except ValueError:
            return jsonify({"error":"invalid_price"}), 400
        if price < 0 or price > 100000000:
            return jsonify({"error":"invalid_price"}), 400

    metadata = dict(row.get("metadata") or {}) if isinstance(row.get("metadata"), dict) else {}
    metadata["description"] = description
    metadata["district"] = address
    if "district_key" in payload:
        district_key = str(payload.get("district_key") or "").strip().lower()
        valid_district_keys = {key for key, _label in realestate_districts_for_data(metadata)}
        if district_key and district_key not in valid_district_keys:
            return jsonify({"error":"invalid_district"}), 400
        metadata["district_key"] = district_key or None
    metadata["contact"] = phone
    metadata["whatsapp"] = whatsapp
    metadata["telegram"] = telegram
    metadata["currency"] = currency
    metadata["price"] = raw_price
    metadata.pop("_telegram_id", None)

    # Повторно ограничиваем UPDATE владельцем на уровне БД.
    # Это защита от гонок между проверкой владения и изменением записи.
    update_payload = {
        "description": description,
        "price": price,
        "currency": currency,
        "phone": phone,
        "address": address,
        "metadata": metadata,
    }

    updated = supabase_request(
        "PATCH",
        "listings",
        params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
        payload=update_payload,
    )

    # Если старые данные metadata мешают PATCH, повторяем только
    # по основным колонкам. Само объявление при этом всё равно
    # обновляется, а расширенные данные останутся в текущем metadata.
    if updated is None:
        core_payload = dict(update_payload)
        core_payload.pop("metadata", None)
        updated = supabase_request(
            "PATCH",
            "listings",
            params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
            payload=core_payload,
        )

    if updated is None:
        # Секрет Supabase сюда никогда не попадает; возвращаем только статус/текст ошибки.
        return jsonify({
            "error":"db_update_failed",
            "detail": LAST_SUPABASE_ERROR or "Supabase отклонил UPDATE",
        }), 503

    # metadata обновляем отдельным запросом только если основной
    # UPDATE прошёл без него. Это защищает редактирование от проблем
    # с JSONB/старыми metadata в конкретной записи.
    if "metadata" not in (updated[0] if isinstance(updated, list) and updated else {}):
        metadata_result = supabase_request(
            "PATCH",
            "listings",
            params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
            payload={"metadata": metadata},
        )
        if metadata_result is None:
            print("MINI APP: metadata update skipped after successful core update")

    # Синхронизируем уже опубликованный текст с каналом.
    if str(row.get("status") or "").lower() == "published":
        edited = dict(metadata)
        edited["category_key"] = edited.get("category_key") or ""
        edited["details"] = dict(edited.get("details") or {})
        edited["photos"] = list(edited.get("photos") or [])
        edited["category"] = edited.get("category") or "Объявление"
        edited["type"] = edited.get("type") or ""
        edited["subcategory"] = edited.get("subcategory") or ""
        edited["description"] = description
        edited["district"] = address
        edited["contact"] = phone
        edited["whatsapp"] = whatsapp
        edited["telegram"] = telegram
        edited["currency"] = currency
        edited["price"] = raw_price
        _sync_edited_listing_to_channel(row, edited)

    return jsonify({"ok":True})


@app.post("/api/my-listing/<int:listing_id>/unpublish")
def mini_app_unpublish_listing(listing_id):
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not row:
        return jsonify({"error":"not_found"}), 404
    status = str(row.get("status") or "").lower()
    if status != "published":
        return jsonify({"ok":True})
    # Do not mark the listing archived if Telegram cleanup failed. The owner can
    # retry; already-deleted messages are treated as complete by the helper.
    if not _delete_listing_channel_messages(row):
        return jsonify({"error":"channel_cleanup_failed"}), 502
    updated = supabase_request(
        "PATCH",
        "listings",
        params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
        payload={"status":"archived","channel_url":"","channel_message_id":None},
    )
    if updated is None:
        return jsonify({"error":"db_update_failed"}), 503
    return jsonify({"ok":True})


@app.post("/api/my-listing/<int:listing_id>/republish")
def mini_app_republish_listing(listing_id):
    """Возвращает снятое объявление в канал и каталог без создания дубля в БД."""
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not row:
        return jsonify({"error":"not_found"}), 404
    status = str(row.get("status") or "").lower()
    if status == "published":
        # The reminder button is shown before expiry, while the listing is still
        # published. Renew by adding 10 days to its current expiry (not silently
        # returning success without changing the date).
        now_utc = datetime.now(timezone.utc)
        raw_expiry = row.get("expires_at")
        if raw_expiry:
            try:
                expiry_dt = datetime.fromisoformat(str(raw_expiry).replace("Z", "+00:00"))
                if expiry_dt.tzinfo is None:
                    expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
            except (TypeError, ValueError):
                return jsonify({"error":"invalid_expiry"}), 409
            renewal_base = max(expiry_dt, now_utc)
        else:
            renewal_base = now_utc
        new_expiry = (renewal_base + timedelta(days=10)).isoformat()
        renewed = supabase_request(
            "PATCH", "listings",
            params={"id":f"eq.{int(listing_id)}", "user_id":f"eq.{user_id}", "status":"eq.published"},
            payload={"expires_at":new_expiry, "reminder_sent_at":None, "reminder_3_sent_at":None, "reminder_2_sent_at":None, "reminder_1_sent_at":None},
        )
        if renewed is None:
            return jsonify({"error":"db_update_failed"}), 503
        load_supabase_published_listings()
        return jsonify({"ok":True, "expires_at":new_expiry, "renewed":True})
    if status != "archived":
        return jsonify({"error":"not_republishable"}), 400

    # Expired listings can be renewed during the two-day grace period only.
    raw_expiry = row.get("expires_at")
    if raw_expiry:
        try:
            expiry_dt = datetime.fromisoformat(str(raw_expiry).replace("Z", "+00:00"))
            if expiry_dt.tzinfo is None:
                expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
            if expiry_dt <= datetime.now(timezone.utc) - timedelta(days=2):
                return jsonify({"error":"renewal_window_closed"}), 410
        except (TypeError, ValueError):
            return jsonify({"error":"invalid_expiry"}), 409

    # Atomic claim: only one request may republish an archived listing at a time.
    # The DB column is added by the companion SQL migration. A stale lock can be
    # reclaimed after five minutes if a worker crashed mid-publication.
    lock_time = _utc_now_iso()
    lock_params = {
        "id": f"eq.{int(listing_id)}",
        "user_id": f"eq.{user_id}",
        "status": "eq.archived",
    }
    claimed = supabase_request(
        "PATCH", "listings",
        params={**lock_params, "republish_lock_at": "is.null"},
        payload={"republish_lock_at": lock_time},
    )
    if claimed is None:
        return jsonify({"error":"db_update_failed"}), 503
    if not claimed:
        stale_before = (datetime.now(timezone.utc) - timedelta(minutes=5)).isoformat()
        claimed = supabase_request(
            "PATCH", "listings",
            params={**lock_params, "republish_lock_at": f"lt.{stale_before}"},
            payload={"republish_lock_at": lock_time},
        )
        if claimed is None:
            return jsonify({"error":"db_update_failed"}), 503
    if not claimed:
        return jsonify({"error":"republish_in_progress"}), 409

    def _release_republish_lock():
        supabase_request(
            "PATCH", "listings",
            params={
                "id": f"eq.{int(listing_id)}",
                "user_id": f"eq.{user_id}",
                "republish_lock_at": f"eq.{lock_time}",
            },
            payload={"republish_lock_at": None},
        )

    metadata = dict(row.get("metadata") or {}) if isinstance(row.get("metadata"), dict) else {}
    data = dict(metadata)
    data["id"] = row.get("id")
    data["description"] = row.get("description") or metadata.get("description") or ""
    data["price"] = str(row.get("price")) if row.get("price") is not None else metadata.get("price", "")
    data["currency"] = row.get("currency") or metadata.get("currency") or "USD"
    data["district"] = row.get("address") or metadata.get("district") or ""
    data["contact"] = row.get("phone") or metadata.get("contact") or ""
    data["whatsapp"] = metadata.get("whatsapp") or ""
    data["telegram"] = metadata.get("telegram") or ""

    # Rebuild only the expected presentation fields from persisted metadata.
    # Synthetic lifecycle-test rows contain no real category/details and must
    # never be sent to the public Telegram channel.
    data["category_key"] = str(metadata.get("category_key") or "").strip()
    data["category"] = str(metadata.get("category") or "").strip()
    data["type"] = str(metadata.get("type") or "").strip()
    data["subcategory"] = str(metadata.get("subcategory") or "").strip()
    data["subcategory_key"] = str(metadata.get("subcategory_key") or "").strip()
    data["details"] = metadata.get("details") if isinstance(metadata.get("details"), dict) else {}
    if not data["category_key"] or not data["category"] or not data["type"]:
        _release_republish_lock()
        print("MINI APP REPUBLISH ERROR: listing_data_incomplete", int(listing_id))
        return jsonify({"error":"listing_data_incomplete"}), 409

    photo_rows = supabase_request(
        "GET", "listing_photos",
        params={"select":"photo_url,sort_order", "listing_id":f"eq.{int(listing_id)}", "order":"sort_order.asc"},
    ) or []
    data["photos"] = [str(x.get("photo_url")) for x in photo_rows if x.get("photo_url")]

    try:
        result = publish_listing(data)
    except Exception as exc:
        print("MINI APP REPUBLISH ERROR:", type(exc).__name__)
        _release_republish_lock()
        return jsonify({"error":"channel_publish_failed"}), 503
    if not result or not result.get("ok"):
        print("MINI APP REPUBLISH ERROR:", result)
        _release_republish_lock()
        return jsonify({"error":"channel_publish_failed"}), 503

    tg_result = result.get("result") if isinstance(result, dict) else None
    message_id = None
    if isinstance(tg_result, list) and tg_result:
        message_id = tg_result[0].get("message_id")
    elif isinstance(tg_result, dict):
        message_id = tg_result.get("message_id")

    channel_url = ""
    if CHANNEL_USERNAME.startswith("@") and message_id:
        channel_url = f"https://t.me/{CHANNEL_USERNAME[1:]}/{message_id}"

    updated = supabase_request(
        "PATCH", "listings",
        params={"id":f"eq.{int(listing_id)}", "user_id":f"eq.{user_id}", "status":"eq.archived", "republish_lock_at":f"eq.{lock_time}"},
        payload={"status":"published", "published_at":_utc_now_iso(), "expires_at":(datetime.now(timezone.utc) + timedelta(days=10)).isoformat(), "reminder_sent_at":None, "reminder_3_sent_at":None, "reminder_2_sent_at":None, "reminder_1_sent_at":None, "channel_url":channel_url, "channel_message_id":message_id, "republish_lock_at":None},
    )
    if updated is None:
        # Не оставляем новое сообщение в канале без связи с объявлением.
        if message_id and CHANNEL_USERNAME:
            try:
                api("deleteMessage", {"chat_id":CHANNEL_USERNAME, "message_id":message_id})
            except Exception:
                pass
        _release_republish_lock()
        return jsonify({"error":"db_update_failed"}), 503

    load_supabase_published_listings()
    return jsonify({"ok":True, "channel_url":channel_url})


@app.delete("/api/my-listing/<int:listing_id>")
def mini_app_delete_listing(listing_id):
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not row:
        return jsonify({"error":"not_found"}), 404
    # Keep the database row and photos until Telegram posts are confirmed deleted.
    # This preserves message IDs so a failed cleanup can be retried safely.
    if not _delete_listing_channel_messages(row):
        return jsonify({"error":"channel_cleanup_failed"}), 502
    photos_deleted = supabase_request(
        "DELETE",
        "listing_photos",
        params={"listing_id":f"eq.{listing_id}"},
    )
    deleted = supabase_request(
        "DELETE",
        "listings",
        params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
    )
    if deleted is None:
        return jsonify({"error":"db_delete_failed"}), 503
    return jsonify({"ok":True})


@app.get("/api/favorites")
def mini_app_favorites():
    if not supabase_enabled():
        return jsonify({"items":[]})
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    user_id = _supabase_user_id(user.get("id"))
    if not user_id:
        return jsonify({"items":[]})
    fav_rows = supabase_request(
        "GET",
        "favorites",
        params={
            "select":"listing_id,created_at",
            "user_id":f"eq.{user_id}",
            "order":"created_at.desc",
            "limit":"200",
        },
    )
    if fav_rows is None:
        return jsonify({"items":[],"error":"db_unavailable"}), 503
    ids=[int(row["listing_id"]) for row in fav_rows if str(row.get("listing_id","")).isdigit()]
    if not ids:
        return jsonify({"items":[]})
    rows = supabase_request(
        "GET",
        "listings",
        params={
            "select":"id,title,description,price,currency,address,phone,metadata,channel_url,created_at,category_id,city_id,status",
            "id":f"in.({','.join(map(str,ids))})",
            "status":"eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "limit":"200",
        },
    )
    if rows is None:
        return jsonify({"items":[],"error":"db_unavailable"}), 503
    by_id={int(row["id"]):row for row in rows if str(row.get("id","")).isdigit()}
    ordered=[by_id[i] for i in ids if i in by_id]
    items=_attach_catalog_photos(ordered)
    for idx,item in enumerate(items):
        row=ordered[idx]
        item["title"]=row.get("title") or item.get("title") or listing_title(item)
        item["description"]=row.get("description") or item.get("description") or ""
        item["price"]=str(row.get("price")) if row.get("price") is not None else item.get("price","")
        item["currency"]=row.get("currency") or item.get("currency","")
        item["address"]=row.get("address") or item.get("district","")
        item["category_name"]=item.get("category") or "Объявление"
        item["channel_post_url"]=row.get("channel_url") or ""
        item["is_favorite"]=True
        _strip_public_listing_fields(item)
        _strip_listing_contact_fields(item)
    return jsonify({"items":items})


@app.post("/api/favorite/<int:listing_id>")
def mini_app_add_favorite(listing_id):
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    user_id = _supabase_user_id(user.get("id"))
    if not user_id:
        return jsonify({"error":"user_not_found"}), 400
    published = supabase_request(
        "GET","listings",
        params={"select":"id","id":f"eq.{listing_id}","status":"eq.published","expires_at":f"gt.{_utc_now_iso()}","limit":"1"},
    )
    if not published:
        return jsonify({"error":"listing_not_found"}), 404
    existing = supabase_request(
        "GET","favorites",
        params={"select":"id","user_id":f"eq.{user_id}","listing_id":f"eq.{listing_id}","limit":"1"},
    )
    if existing:
        return jsonify({"ok":True,"favorite":True})
    created = supabase_request(
        "POST","favorites",
        payload={"user_id":user_id,"listing_id":listing_id},
    )
    if created is None:
        return jsonify({"error":"db_insert_failed"}), 503
    return jsonify({"ok":True,"favorite":True})


