@app.get("/api/auto-options")
def mini_app_auto_options():
    """Возвращает марки и модели для фильтра Авто. Марки берутся из опубликованных
    объявлений; если объявлений пока нет, показываем базовый список популярных марок,
    чтобы пользователь мог выбрать марку уже сейчас. Модели остаются привязанными
    к реально найденным объявлениям.
    """
    city = str(request.args.get("city", DEFAULT_CITY_SLUG)).strip().lower()
    if city != "all" and not re.fullmatch(r"[\w-]{2,40}", city, flags=re.UNICODE):
        city = DEFAULT_CITY_SLUG

    # Большой базовый каталог марок и популярных моделей.
    # Важно: это именно fallback-каталог — объявления пользователей дополняют его,
    # а не заменяют его. Поэтому даже при одном объявлении Audi пользователь всё равно
    # видит весь список марок и основные модели.
    fallback_data = AUTO_FALLBACK_DATA
    fallback_makes = sorted(fallback_data.keys(), key=str.casefold)
    fallback_models = {k.casefold(): v for k, v in fallback_data.items()}

    if not supabase_enabled():
        return jsonify({"makes": fallback_makes, "models": []})

    city_id = _supabase_city_id(city)
    category_id = _supabase_category_id("auto")
    if not city_id or not category_id:
        return jsonify({"makes": fallback_makes, "models": []})

    make_filter = str(request.args.get("make", "")).strip().casefold()
    rows = supabase_request(
        "GET",
        "listings",
        params={
            "select":"metadata,title",
            "status":"eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "city_id":f"eq.{city_id}",
            "category_id":f"eq.{category_id}",
            "limit":"1000",
        },
    )
    if rows is None:
        return jsonify({"makes": fallback_makes, "models": [], "error":"db_unavailable"}), 503

    pairs = set()
    for row in rows:
        meta = row.get("metadata") or {}
        if not isinstance(meta, dict):
            continue
        details = meta.get("details") if isinstance(meta.get("details"), dict) else {}

        make = str(details.get("make") or "").strip()
        model = str(details.get("model") or "").strip()
        combined = str(details.get("make_model") or "").strip()

        if (not make or not model) and combined:
            # Поддержка старого формата "Toyota Camry".
            parts = combined.split()
            if not make and parts:
                make = parts[0]
            if not model and len(parts) > 1:
                model = " ".join(parts[1:])

        if not make:
            title = str(row.get("title") or "").strip()
            if title:
                clean = title.split("·", 1)[0].strip()
                parts = clean.split()
                if parts:
                    make = parts[0]
                    model = " ".join(parts[1:]) if len(parts) > 1 else model

        if make:
            pairs.add((make, model))

    db_makes = {make for make, _ in pairs if make}
    # База объявлений только дополняет каталог. Она не должна скрывать марки,
    # которые ещё никто не разместил.
    makes = sorted(set(fallback_makes) | db_makes, key=str.casefold)

    db_models = {
        model for make, model in pairs
        if make_filter and make.casefold() == make_filter and model
    }
    base_models = set(fallback_models.get(make_filter, [])) if make_filter else set()
    models = sorted(base_models | db_models, key=str.casefold)
    return jsonify({"makes": makes, "models": models})


@app.get("/api/listings")
def mini_app_listings():
    _perf_started = time.perf_counter()
    if not supabase_enabled():
        return jsonify({"items":[],"has_next":False,"total_hint":0})

    city = str(request.args.get("city", DEFAULT_CITY_SLUG)).strip().lower()
    if city != "all" and not re.fullmatch(r"[\w-]{2,40}", city, flags=re.UNICODE):
        city = DEFAULT_CITY_SLUG
    category = str(request.args.get("category", "")).strip().lower()
    q = str(request.args.get("q", "")).strip()[:80]
    try:
        page = max(0, int(request.args.get("page", "0")))
        per_page = min(20, max(1, int(request.args.get("per_page", "20"))))
    except ValueError:
        page, per_page = 0, 20

    # City lookup and Telegram identity lookup are independent. Run the city
    # lookup in the read executor while validating the current Telegram user.
    # This overlaps network waits without changing listing or favorite semantics.
    _perf_phase_started = time.perf_counter()
    city_future = LISTING_READ_EXECUTOR.submit(_supabase_city_id, city) if city != "all" else None
    # Resolve the currently supported city IDs so cards can display each listing's
    # actual city when the user selects All. Unknown future city IDs remain blank
    # rather than incorrectly inheriting the selected city.
    city_ids_by_slug = {}
    if city == "all":
        # Resolve every city registered in Supabase, not only Batumi/Tbilisi.
        # This keeps the "All" feed truly cross-city and lets each card show
        # the listing's own city rather than inheriting the selected filter.
        _city_rows = supabase_request(
            "GET", "cities", params={"select": "id,slug", "limit": "500"}
        ) or []
        for _city_row in _city_rows:
            try:
                _cid = int(_city_row.get("id"))
                _slug = str(_city_row.get("slug") or "").strip().lower()
                if _slug:
                    city_ids_by_slug[_cid] = _slug
            except (TypeError, ValueError):
                continue
    _perf_auth_started = time.perf_counter()
    current_user = _mini_app_authenticated_user()
    print(f"PERF listings_phase=telegram_auth ms={(time.perf_counter() - _perf_auth_started) * 1000:.1f} valid={int(bool(current_user))}")
    _perf_user_started = time.perf_counter()
    current_user_id = _supabase_user_id(current_user.get("id")) if current_user else None
    print(f"PERF listings_phase=user_id_lookup ms={(time.perf_counter() - _perf_user_started) * 1000:.1f} found={int(bool(current_user_id))}")
    city_id = city_future.result() if city_future is not None else None
    print(f"PERF listings_phase=city_lookup ms={(time.perf_counter() - _perf_phase_started) * 1000:.1f}")
    if city != "all" and not city_id:
        return jsonify({"items":[],"has_next":False,"total_hint":0})

    category_id = None
    if category:
        category_id = _supabase_category_id(category)
        if not category_id:
            return jsonify({"items":[],"has_next":False,"total_hint":0})

    cursor_requested = str(request.args.get("cursor_mode", "")).strip() == "1"
    cursor_filter_names = (
        "deal", "sub", "min_price", "max_price", "rooms", "min_area", "max_area",
        "district", "make", "model", "min_year", "max_year", "min_mileage", "max_mileage",
        "condition", "pet_age", "pet_breed", "pet_gender",
    )
    cursor_has_advanced_filters = any(str(request.args.get(name, "")).strip() for name in cursor_filter_names)
    # Generic-category free-text search must use the server-side matcher below,
    # which searches title, description, address and phone. The cursor RPC does
    # not currently include the phone column in its text haystack.
    generic_filter_categories = {"tech", "home", "kids", "work", "services", "pets", "give", "search"}
    generic_text_search = category in generic_filter_categories and bool(q)
    # The cursor RPC searches text fields but does not include the phone column.
    # Route phone-like queries through the regular candidate path, which selects
    # `phone` and normalizes its digits before matching.
    query_phone_digits = re.sub(r"\\D", "", q)
    phone_like_search = len(query_phone_digits) >= 6
    cursor_mode_active = (
        city != "all"
        and cursor_requested
        and not cursor_has_advanced_filters
        and not generic_text_search
        and not phone_like_search
    )

    if cursor_mode_active:
        raw_cursor_id = str(request.args.get("cursor_id", "")).strip()
        try:
            cursor_id = int(raw_cursor_id) if raw_cursor_id else None
            if cursor_id is not None and cursor_id <= 0:
                cursor_id = None
        except (TypeError, ValueError):
            cursor_id = None
        _perf_phase_started = time.perf_counter()
        cursor_rows = supabase_request(
            "POST",
            "rpc/mm_search_cursor_listings",
            payload={
                "p_city_id": int(city_id),
                "p_category_id": int(category_id) if category_id else None,
                "p_query": q or None,
                "p_sort": str(request.args.get("sort", "new")).strip().lower(),
                "p_cursor_id": cursor_id,
                "p_limit": per_page + 1,
            },
        )
        print(f"PERF listings_phase=cursor_rpc ms={(time.perf_counter() - _perf_phase_started) * 1000:.1f} rows={len(cursor_rows) if isinstance(cursor_rows, list) else -1}")
        if cursor_rows is None:
            return jsonify({"items": [], "has_next": False, "total_hint": 0, "error": "cursor_search_unavailable"}), 503
        has_next = len(cursor_rows) > per_page
        rows = cursor_rows[:per_page]
        next_cursor_id = rows[-1].get("id") if has_next and rows else None
    else:
        next_cursor_id = None

    if not cursor_mode_active:
        params = {
            "select":"id,title,description,price,currency,price_usd,address,metadata,phone,channel_url,created_at,category_id,city_id,status",
            "status":"eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "order":"created_at.desc",
        }
        if city != "all":
            params["city_id"] = f"eq.{city_id}"
        else:
            # A non-null city_id includes listings from every configured city.
            params["city_id"] = "not.is.null"
        if category_id:
            params["category_id"] = f"eq.{category_id}"

        # Push safe, exact filters into PostgREST before loading candidates.
        # Python checks remain as a defensive consistency check.
        selected_deal_db = str(request.args.get("deal", "")).strip().lower()
        generic_filter_categories = {"tech", "home", "kids", "work", "services", "pets", "give", "search"}
        if category == "realestate" and selected_deal_db in {"rent", "seek", "sell", "buy"}:
            params["metadata->>type_key"] = f"eq.{selected_deal_db}"
        elif category == "auto" and selected_deal_db in {"sell", "buy"}:
            params["metadata->>type_key"] = f"eq.{selected_deal_db}"
        elif category in generic_filter_categories and selected_deal_db:
            params["metadata->>type_key"] = f"eq.{selected_deal_db}"

        selected_sub_db = str(request.args.get("sub", "")).strip().lower()
        allowed_realestate_subs = {"apartment", "house", "commercial", "land", "garage"}
        if selected_sub_db and (category in generic_filter_categories or (category == "realestate" and selected_sub_db in allowed_realestate_subs)):
            params["metadata->>subcategory_key"] = f"eq.{selected_sub_db}"

        # Price is a numeric table column, so valid bounds can be filtered in SQL
        # instead of downloading thousands of rows and discarding most in Python.
        price_conditions = []
        for request_name, operator in (("min_price", "gte"), ("max_price", "lte")):
            raw_price = str(request.args.get(request_name, "")).strip().replace(",", ".")
            if raw_price:
                try:
                    price_bound = float(raw_price)
                    import math
                    if price_bound >= 0 and math.isfinite(price_bound):
                        price_conditions.append(f"price_usd.{operator}.{price_bound}")
                except (TypeError, ValueError):
                    pass
        if len(price_conditions) == 1:
            _, operator, value = price_conditions[0].split(".", 2)
            params["price_usd"] = f"{operator}.{value}"
        elif len(price_conditions) == 2:
            params["and"] = f"({','.join(price_conditions)})"

        def _fetch_listing_candidates(query_params, max_candidates=10000, batch_size=1000):
            """Fetch a bounded, stable set of listing candidates in API-sized batches."""
            candidates = []
            paged_params = dict(query_params)
            paged_params["limit"] = str(batch_size)
            for candidate_offset in range(0, max_candidates, batch_size):
                paged_params["offset"] = str(candidate_offset)
                batch = supabase_request("GET", "listings", params=paged_params)
                if batch is None:
                    return None
                candidates.extend(batch)
                if len(batch) < batch_size:
                    break
            return candidates

        # Search is applied in Python to the candidate rows so it can match
        # title, description, address and saved metadata consistently, including
        # Russian category/subcategory details. Avoid fragile PostgREST `or`
        # syntax for free-text input.
        def _matches_search(row):
            if not q:
                return True
            metadata = row.get("metadata") or {}
            try:
                metadata_text = json.dumps(metadata, ensure_ascii=False, default=str)
            except (TypeError, ValueError):
                metadata_text = str(metadata)
            haystack = " ".join((
                str(row.get("title") or ""),
                str(row.get("description") or ""),
                str(row.get("address") or ""),
                str(row.get("phone") or ""),
                metadata_text,
            )).casefold()
            # Also search a compact digit-only phone representation, so queries
            # with or without spaces, parentheses, +, or hyphens match the same number.
            phone_digits = re.sub(r"\D", "", str(row.get("phone") or ""))
            if phone_digits:
                haystack += " " + phone_digits
            synonym_groups = {
                "квартира": ("квартира", "квартиры", "квартиру", "квартире", "apartment", "apartments"),
                "квартиры": ("квартира", "квартиры", "квартиру", "квартире", "apartment", "apartments"),
                "квартиру": ("квартира", "квартиры", "квартиру", "квартире", "apartment", "apartments"),
                "телефон": ("телефон", "телефоны", "phone", "smartphone"),
                "телефоны": ("телефон", "телефоны", "phone", "smartphone"),
                "машина": ("машина", "авто", "автомобиль", "car", "auto"),
                "автомобиль": ("машина", "авто", "автомобиль", "car", "auto"),
            }
            terms = [term.casefold() for term in q.split() if term.strip()]
            return all(any(alias in haystack for alias in synonym_groups.get(term, (term,))) for term in terms)

        sort_mode = str(request.args.get("sort", "new")).strip().lower()
        if sort_mode not in {"new", "price_asc", "price_desc"}:
            sort_mode = "new"
        params["order"] = "created_at.desc" if sort_mode == "new" else ("price_usd.asc.nullslast,created_at.desc" if sort_mode == "price_asc" else "price_usd.desc.nullslast,created_at.desc")

        # Shared numeric parser must be defined before the auto/generic filter branches.
        # Otherwise Python treats a later nested definition as a local variable and
        # raises UnboundLocalError when an earlier branch calls it.
        def _generic_num(v):
            try:
                return float(str(v).replace(",", ".").replace("km", "").replace("км", "").strip())
            except (TypeError, ValueError):
                return None

        # Фильтры недвижимости применяем в Python после получения ограниченного
        # набора кандидатов. Это специально сделано так, чтобы не зависеть от
        # типов колонок/JSON-path синтаксиса PostgREST и не получать HTTP 400.
        # Для площади и 4+ комнат нужен числовой разбор JSON metadata.
        # Берём ограниченный набор кандидатов, уже отфильтрованный Supabase
        # по городу/категории/цене/типу/району.
        # Only filters that still require Python should force a large candidate scan.
        # Exact type/subcategory and numeric price bounds are already applied in params.
        # If text search is combined with those filters, keep the existing Python path
        # for now because the RPC does not yet accept these additional filter values.
        db_filter_names = ("deal", "sub", "min_price", "max_price")
        has_search_with_db_filters = bool(q) and any(
            str(request.args.get(name, "")).strip() for name in db_filter_names
        )
        has_python_filters = category == "realestate" and (
            any(str(request.args.get(name, "")).strip() for name in ("rooms", "min_area", "max_area", "district"))
            or has_search_with_db_filters
        )
        has_auto_filters = city != "all" and category == "auto" and (
            any(str(request.args.get(name, "")).strip() for name in ("make", "model", "min_year", "max_year", "min_mileage", "max_mileage"))
            or has_search_with_db_filters
        )
        has_generic_filters = city != "all" and category in {"tech", "home", "kids", "work", "services", "pets", "give", "search"} and (
            any(str(request.args.get(name, "")).strip() for name in ("condition", "make", "model", "pet_age", "pet_breed", "pet_gender"))
            or has_search_with_db_filters
        )

        # Combined free-text search + advanced filters for real estate and auto
        # are executed in PostgreSQL. This avoids the legacy 10,000-row Python scan
        # while leaving the already-working standalone search/filter paths unchanged.
        # Use the combined PostgreSQL RPC whenever it can replace a Python-side
        # candidate scan: text + advanced filters, real-estate district filtering,
        # and auto subcategory filtering. The RPC supports an empty p_query, so
        # these cases can be paginated in PostgreSQL even without free-text input.
        has_combined_advanced_search = (
            city != "all" and (
            (
                category == "realestate"
                and (
                    (bool(q) and any(
                        str(request.args.get(name, "")).strip()
                        for name in ("deal", "sub", "min_price", "max_price", "rooms", "min_area", "max_area", "district")
                    ))
                    or bool(str(request.args.get("district", "")).strip())
                )
            )
            or (
                category == "auto"
                and (
                    (bool(q) and any(
                        str(request.args.get(name, "")).strip()
                        for name in ("deal", "sub", "make", "model", "min_price", "max_price",
                                     "min_year", "max_year", "min_mileage", "max_mileage")
                    ))
                    or bool(str(request.args.get("sub", "")).strip())
                )
            )
            )
        )

        def _combined_rpc_num(name):
            raw = str(request.args.get(name, "")).strip().lower()
            if not raw:
                return None
            raw = raw.replace(",", ".").replace("km", "").replace("км", "").replace("м²", "").replace("m²", "").strip()
            try:
                value = float(raw)
                import math
                return value if math.isfinite(value) and value >= 0 else None
            except (TypeError, ValueError):
                return None

        if has_combined_advanced_search:
            selected_rooms_combined = str(request.args.get("rooms", "")).strip()
            min_rooms_combined = max_rooms_combined = None
            if selected_rooms_combined in {"1", "2", "3"}:
                min_rooms_combined = max_rooms_combined = int(selected_rooms_combined)
            elif selected_rooms_combined == "4":
                min_rooms_combined = 4

            offset = page * per_page
            combined_rows = supabase_request(
                "POST",
                "rpc/mm_search_filtered_listings",
                payload={
                    "p_city_id": int(city_id),
                    "p_category_id": int(category_id),
                    "p_category_key": category,
                    "p_query": q,
                    "p_deal": str(request.args.get("deal", "")).strip().lower() or None,
                    "p_subcategory": str(request.args.get("sub", "")).strip().lower() or None,
                    "p_make": str(request.args.get("make", "")).strip() or None,
                    "p_model": str(request.args.get("model", "")).strip() or None,
                    "p_min_price": _combined_rpc_num("min_price"),
                    "p_max_price": _combined_rpc_num("max_price"),
                    "p_min_year": _combined_rpc_num("min_year"),
                    "p_max_year": _combined_rpc_num("max_year"),
                    "p_min_mileage": _combined_rpc_num("min_mileage"),
                    "p_max_mileage": _combined_rpc_num("max_mileage"),
                    "p_min_area": _combined_rpc_num("min_area"),
                    "p_max_area": _combined_rpc_num("max_area"),
                    "p_min_rooms": min_rooms_combined,
                    "p_max_rooms": max_rooms_combined,
                    "p_district": str(request.args.get("district", "")).strip() or None,
                    "p_sort": sort_mode,
                    "p_offset": offset,
                    "p_limit": per_page + 1,
                },
            )
            if combined_rows is None:
                return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"combined_search_unavailable"}), 503
            has_next = len(combined_rows) > per_page
            rows = combined_rows[:per_page]

        # For real-estate filters, use the database RPC so numeric filtering,
        # ordering and pagination happen in PostgreSQL instead of scanning listings in Python.
        # Keep the established Python path for free-text search and district filtering,
        # which are not parameters of mm_filter_realestate_listings.
        realestate_filter_names = ("deal", "sub", "min_price", "max_price", "rooms", "min_area", "max_area")
        has_realestate_rpc_filters = (
            city != "all"
            and category == "realestate"
            and not q
            and not str(request.args.get("district", "")).strip()
            and any(str(request.args.get(name, "")).strip() for name in realestate_filter_names)
        )

        if not has_combined_advanced_search and has_realestate_rpc_filters:
            def _rpc_num(name):
                raw = str(request.args.get(name, "")).strip().replace(",", ".")
                if not raw:
                    return None
                try:
                    value = float(raw)
                    import math
                    return value if math.isfinite(value) and value >= 0 else None
                except (TypeError, ValueError):
                    return None

            selected_deal_rpc = str(request.args.get("deal", "")).strip().lower()
            if selected_deal_rpc not in {"rent", "seek", "sell", "buy"}:
                selected_deal_rpc = None
            selected_sub_rpc = str(request.args.get("sub", "")).strip().lower()
            if selected_sub_rpc not in allowed_realestate_subs:
                selected_sub_rpc = None

            selected_rooms_rpc = str(request.args.get("rooms", "")).strip()
            min_rooms_rpc = max_rooms_rpc = None
            if selected_rooms_rpc in {"1", "2", "3"}:
                min_rooms_rpc = max_rooms_rpc = int(selected_rooms_rpc)
            elif selected_rooms_rpc == "4":
                min_rooms_rpc = 4

            offset = page * per_page
            filtered_rows = supabase_request(
                "POST",
                "rpc/mm_filter_realestate_listings",
                payload={
                    "p_city_id": city_id,
                    "p_category_id": category_id,
                    "p_deal": selected_deal_rpc,
                    "p_subcategory": selected_sub_rpc,
                    "p_min_price": _rpc_num("min_price"),
                    "p_max_price": _rpc_num("max_price"),
                    "p_min_area": _rpc_num("min_area"),
                    "p_max_area": _rpc_num("max_area"),
                    "p_min_rooms": min_rooms_rpc,
                    "p_max_rooms": max_rooms_rpc,
                    "p_min_floor": None,
                    "p_max_floor": None,
                    "p_sort": sort_mode,
                    "p_offset": offset,
                    "p_limit": per_page + 1,
                },
            )
            if filtered_rows is None:
                return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"realestate_filter_unavailable"}), 503
            has_next = len(filtered_rows) > per_page
            rows = filtered_rows[:per_page]
        elif not has_combined_advanced_search and has_auto_filters and not q and not str(request.args.get("sub", "")).strip():
            # Use the database RPC for automotive attributes, sorting and pagination.
            # Keep the established Python path when free-text search or subcategory
            # is active because the RPC does not accept those parameters.
            def _auto_rpc_num(name):
                raw = str(request.args.get(name, "")).strip().lower()
                if not raw:
                    return None
                raw = raw.replace(",", ".").replace("km", "").replace("км", "").strip()
                try:
                    value = float(raw)
                    import math
                    return value if math.isfinite(value) and value >= 0 else None
                except (TypeError, ValueError):
                    return None

            offset = page * per_page
            auto_rows = supabase_request(
                "POST",
                "rpc/mm_filter_auto_listings",
                payload={
                    "p_city_id": int(city_id),
                    "p_category_id": int(category_id),
                    "p_deal": str(request.args.get("deal", "")).strip().lower() or None,
                    "p_make": str(request.args.get("make", "")).strip() or None,
                    "p_model": str(request.args.get("model", "")).strip() or None,
                    "p_min_price": _auto_rpc_num("min_price"),
                    "p_max_price": _auto_rpc_num("max_price"),
                    "p_min_year": _auto_rpc_num("min_year"),
                    "p_max_year": _auto_rpc_num("max_year"),
                    "p_min_mileage": _auto_rpc_num("min_mileage"),
                    "p_max_mileage": _auto_rpc_num("max_mileage"),
                    "p_sort": sort_mode,
                    "p_offset": offset,
                    "p_limit": per_page + 1,
                },
            )
            if auto_rows is None:
                return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"auto_filter_unavailable"}), 503
            has_next = len(auto_rows) > per_page
            rows = auto_rows[:per_page]
        elif not has_combined_advanced_search and has_python_filters:
            rows = _fetch_listing_candidates(params)
            if rows is None:
                return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"db_unavailable"}), 503

            min_area = request.args.get("min_area", "").strip()
            max_area = request.args.get("max_area", "").strip()
            try: min_area_n = float(min_area) if min_area else None
            except ValueError: min_area_n = None
            try: max_area_n = float(max_area) if max_area else None
            except ValueError: max_area_n = None

            filtered = []
            selected_deal = str(request.args.get("deal", "")).strip().lower()
            selected_sub = str(request.args.get("sub", "")).strip().lower()
            selected_rooms = str(request.args.get("rooms", "")).strip()
            for row in rows:
                if not _matches_search(row):
                    continue
                meta = row.get("metadata") or {}
                meta = meta if isinstance(meta, dict) else {}
                details = meta.get("details") if isinstance(meta.get("details"), dict) else {}

                # Цена
                price_value = row.get("price_usd", row.get("price"))
                try:
                    price_n = float(str(price_value).replace(",", ".").strip())
                except (TypeError, ValueError):
                    price_n = None
                min_price_raw = str(request.args.get("min_price", "")).strip()
                max_price_raw = str(request.args.get("max_price", "")).strip()
                try: min_price_n = float(min_price_raw) if min_price_raw else None
                except ValueError: min_price_n = None
                try: max_price_n = float(max_price_raw) if max_price_raw else None
                except ValueError: max_price_n = None
                if min_price_n is not None and (price_n is None or price_n < min_price_n):
                    continue
                if max_price_n is not None and (price_n is None or price_n > max_price_n):
                    continue

                # Район / адрес
                selected_district = str(request.args.get("district", "")).strip().lower()
                if selected_district:
                    saved_district_key = str(meta.get("district_key") or "").strip().lower()
                    if saved_district_key:
                        if saved_district_key != selected_district:
                            continue
                    else:
                        # Backward compatibility only for old records without a saved key.
                        address_text = str(row.get("address", "") or "").casefold()
                        legacy_labels = {
                            "old_batumi": ("старый батуми", "old batumi"),
                            "new_boulevard": ("новый бульвар", "new boulevard"),
                            "khimshiashvili": ("химшиашвили", "khimshiashvili"),
                            "bagrationi": ("багратиони", "bagrationi"),
                            "angisa": ("ангиса", "angisa"),
                            "airport": ("аэропорт", "airport"),
                            "gonio": ("гонио", "gonio"),
                            "kvariati": ("квариати", "kvariati"),
                            "makhinjauri": ("махинджаури", "makhinjauri"),
                        }
                        labels = legacy_labels.get(selected_district, (selected_district,))
                        if not any(label in address_text for label in labels):
                            continue

                if selected_deal and selected_deal in {"rent", "seek", "sell", "buy"}:
                    if str(meta.get("type_key", "")).strip().lower() != selected_deal:
                        continue
                if selected_sub and selected_sub in {"apartment", "house", "commercial", "land", "garage"}:
                    if str(meta.get("subcategory_key", "")).strip().lower() != selected_sub:
                        continue

                if selected_rooms in {"1", "2", "3"}:
                    try:
                        if float(str(details.get("rooms", "")).replace(",", ".")) != float(selected_rooms):
                            continue
                    except (TypeError, ValueError):
                        continue
                elif selected_rooms == "4":
                    try:
                        if float(str(details.get("rooms", "")).replace(",", ".")) < 4:
                            continue
                    except (TypeError, ValueError):
                        continue
                if min_area_n is not None or max_area_n is not None:
                    try: area_n = float(str(details.get("area", "")).replace(",", ".").replace("м²", "").replace("m²", "").strip())
                    except (TypeError, ValueError):
                        continue
                    if min_area_n is not None and area_n < min_area_n: continue
                    if max_area_n is not None and area_n > max_area_n: continue
                filtered.append(row)
            def _sort_price(row):
                try:
                    return float(str(row.get("price_usd", row.get("price")) or "").replace(",", ".").strip())
                except (TypeError, ValueError):
                    return None
            if sort_mode == "price_asc":
                filtered.sort(key=lambda r: (_sort_price(r) is None, _sort_price(r) if _sort_price(r) is not None else 0))
            elif sort_mode == "price_desc":
                filtered.sort(key=lambda r: (_sort_price(r) is not None, _sort_price(r) if _sort_price(r) is not None else 0), reverse=True)

            offset = page * per_page
            page_rows = filtered[offset:offset + per_page]
            has_next = len(filtered) > offset + per_page
            rows = page_rows
        elif not has_combined_advanced_search and has_auto_filters:
            rows = _fetch_listing_candidates(params)
            if rows is None:
                return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"db_unavailable"}), 503

            def _num(v):
                try:
                    return float(str(v).replace(",", ".").replace("km","").replace("км","").strip())
                except (TypeError, ValueError):
                    return None

            selected_deal = str(request.args.get("deal", "")).strip().lower()
            selected_make = str(request.args.get("make", "")).strip().lower()
            selected_model = str(request.args.get("model", "")).strip().lower()
            min_price_n = _num(request.args.get("min_price", ""))
            max_price_n = _num(request.args.get("max_price", ""))
            min_year_n = _num(request.args.get("min_year", ""))
            max_year_n = _num(request.args.get("max_year", ""))
            min_mileage_n = _num(request.args.get("min_mileage", ""))
            max_mileage_n = _num(request.args.get("max_mileage", ""))

            filtered = []
            for row in rows:
                if not _matches_search(row):
                    continue
                meta = row.get("metadata") or {}
                meta = meta if isinstance(meta, dict) else {}
                details = meta.get("details") if isinstance(meta.get("details"), dict) else {}
                if selected_deal in {"sell","buy"} and str(meta.get("type_key","")).strip().lower() != selected_deal:
                    continue
                price_n = _generic_num(row.get("price_usd", row.get("price")))
                if min_price_n is not None and (price_n is None or price_n < min_price_n): continue
                if max_price_n is not None and (price_n is None or price_n > max_price_n): continue
                make_text = str(details.get("make") or details.get("make_model") or "").strip().lower()
                model_text = str(details.get("model") or details.get("make_model") or "").strip().lower()
                combined = f"{make_text} {model_text}".strip()
                if selected_make and selected_make not in combined: continue
                if selected_model and selected_model not in combined: continue
                year_n = _num(details.get("year"))
                if min_year_n is not None and (year_n is None or year_n < min_year_n): continue
                if max_year_n is not None and (year_n is None or year_n > max_year_n): continue
                mileage_n = _num(details.get("mileage"))
                if min_mileage_n is not None and (mileage_n is None or mileage_n < min_mileage_n): continue
                if max_mileage_n is not None and (mileage_n is None or mileage_n > max_mileage_n): continue
                filtered.append(row)

            if sort_mode == "price_asc":
                filtered.sort(key=lambda r: (_generic_num(r.get("price_usd", r.get("price"))) is None, _generic_num(r.get("price_usd", r.get("price"))) if _generic_num(r.get("price_usd", r.get("price"))) is not None else 0))
            elif sort_mode == "price_desc":
                filtered.sort(key=lambda r: (_generic_num(r.get("price_usd", r.get("price"))) is not None, _generic_num(r.get("price_usd", r.get("price"))) if _generic_num(r.get("price_usd", r.get("price"))) is not None else 0), reverse=True)

            offset = page * per_page
            page_rows = filtered[offset:offset + per_page]
            has_next = len(filtered) > offset + per_page
            rows = page_rows
        elif not has_combined_advanced_search and category in generic_filter_categories and (
            q or (category == "tech" and any(
                str(request.args.get(name, "")).strip() for name in ("make", "model")
            ))
        ):
            # Generic-category text search: keep the selected category/filters and
            # search title, description, address, metadata and phone consistently.
            # Technology brand/model filters also use this path even without q,
            # because technology listings store their selected brand in details.brand_model
            # while the generic SQL RPC primarily checks details.make_model.
            # This is deliberately isolated from real-estate and auto branches.
            rows = _fetch_listing_candidates(params)
            if rows is None:
                return jsonify({"items": [], "has_next": False, "total_hint": 0, "error": "generic_search_unavailable"}), 503

            selected_deal_generic = str(request.args.get("deal", "")).strip().lower()
            selected_sub_generic = str(request.args.get("sub", "")).strip().lower()
            selected_condition_generic = str(request.args.get("condition", "")).strip().casefold()
            selected_make_generic = str(request.args.get("make", "")).strip().casefold()
            selected_model_generic = str(request.args.get("model", "")).strip().casefold()
            selected_pet_age_generic = str(request.args.get("pet_age", "")).strip().casefold()
            selected_pet_breed_generic = str(request.args.get("pet_breed", "")).strip().casefold()
            selected_pet_gender_generic = str(request.args.get("pet_gender", "")).strip().casefold()
            selected_district_generic = str(request.args.get("district", "")).strip().casefold()
            min_price_generic = _generic_num(request.args.get("min_price", ""))
            max_price_generic = _generic_num(request.args.get("max_price", ""))

            filtered_generic = []
            for row in rows:
                if not _matches_search(row):
                    continue
                meta = row.get("metadata") or {}
                meta = meta if isinstance(meta, dict) else {}
                details = meta.get("details") if isinstance(meta.get("details"), dict) else {}
                if selected_deal_generic and str(meta.get("type_key", "")).strip().lower() != selected_deal_generic:
                    continue
                if selected_sub_generic and str(meta.get("subcategory_key", "")).strip().lower() != selected_sub_generic:
                    continue

                price_generic = _generic_num(row.get("price_usd", row.get("price")))
                if min_price_generic is not None and (price_generic is None or price_generic < min_price_generic):
                    continue
                if max_price_generic is not None and (price_generic is None or price_generic > max_price_generic):
                    continue

                details_text = json.dumps(details, ensure_ascii=False, default=str).casefold()
                if selected_condition_generic and selected_condition_generic not in details_text:
                    continue
                if selected_make_generic:
                    if category == "tech":
                        # Match the structured brand fields first, with title/description
                        # as a compatibility fallback for older listings lacking brand_model.
                        brand_values = [
                            details.get("brand_model"), details.get("brand"),
                            details.get("make"), details.get("make_model"),
                            row.get("title"), row.get("description"),
                        ]
                        brand_text = " ".join(str(value or "") for value in brand_values).casefold()
                        if selected_make_generic not in brand_text:
                            continue
                    elif selected_make_generic not in details_text:
                        continue
                if selected_model_generic:
                    if category == "tech":
                        model_values = [
                            details.get("brand_model"), details.get("model"),
                            details.get("make_model"), row.get("title"), row.get("description"),
                        ]
                        model_text = " ".join(str(value or "") for value in model_values).casefold()
                        if selected_model_generic not in model_text:
                            continue
                    elif selected_model_generic not in details_text:
                        continue
                if selected_pet_breed_generic and selected_pet_breed_generic not in details_text:
                    continue
                if selected_pet_gender_generic and selected_pet_gender_generic not in details_text:
                    continue
                if selected_pet_age_generic:
                    # Pet-age range controls use range:years|min|max / range:months|min|max.
                    age_match = re.fullmatch(r"range:(years|months):([^:]*):([^:]*)", selected_pet_age_generic)
                    if age_match:
                        age_text = str(details.get("age", "")).casefold()
                        age_num_match = re.search(r"(\d+(?:[.,]\d+)?)", age_text)
                        if not age_num_match:
                            continue
                        try:
                            age_num = float(age_num_match.group(1).replace(",", "."))
                            age_min = float(age_match.group(2)) if age_match.group(2) else None
                            age_max = float(age_match.group(3)) if age_match.group(3) else None
                        except ValueError:
                            continue
                        if age_match.group(1) == "months" and "лет" not in age_text and "год" not in age_text:
                            age_num /= 12.0
                        if age_min is not None and age_num < age_min:
                            continue
                        if age_max is not None and age_num > age_max:
                            continue
                    elif selected_pet_age_generic not in details_text:
                        continue

                if selected_district_generic:
                    district_key_generic = str(meta.get("district_key") or "").strip().casefold()
                    address_generic = str(row.get("address") or "").casefold()
                    if selected_district_generic != district_key_generic and selected_district_generic not in address_generic:
                        continue
                filtered_generic.append(row)

            if sort_mode == "price_asc":
                filtered_generic.sort(key=lambda r: (_generic_num(r.get("price_usd", r.get("price"))) is None, _generic_num(r.get("price_usd", r.get("price"))) if _generic_num(r.get("price_usd", r.get("price"))) is not None else 0))
            elif sort_mode == "price_desc":
                filtered_generic.sort(key=lambda r: (_generic_num(r.get("price_usd", r.get("price"))) is not None, _generic_num(r.get("price_usd", r.get("price"))) if _generic_num(r.get("price_usd", r.get("price"))) is not None else 0), reverse=True)

            offset = page * per_page
            rows = filtered_generic[offset:offset + per_page]
            has_next = len(filtered_generic) > offset + per_page
        elif not has_combined_advanced_search and has_generic_filters:
            # Run generic category filters in PostgreSQL. This removes the old
            # 10,000-row Python scan for condition/brand/pet filters.
            offset = page * per_page
            generic_rows = supabase_request(
                "POST",
                "rpc/mm_filter_generic_listings",
                payload={
                    "p_city_id": int(city_id),
                    "p_category_id": int(category_id),
                    "p_deal": str(request.args.get("deal", "")).strip().lower() or None,
                    "p_subcategory": str(request.args.get("sub", "")).strip().lower() or None,
                    "p_condition": str(request.args.get("condition", "")).strip().lower() or None,
                    "p_make": str(request.args.get("make", "")).strip() or None,
                    "p_model": str(request.args.get("model", "")).strip() or None,
                    "p_pet_age": str(request.args.get("pet_age", "")).strip() or None,
                    "p_pet_breed": str(request.args.get("pet_breed", "")).strip() or None,
                    "p_pet_gender": ({"male": "male", "female": "female", "unknown": "unknown"}.get(str(request.args.get("pet_gender", "")).strip().lower()) or None),
                    "p_min_price": _generic_num(request.args.get("min_price", "")),
                    "p_max_price": _generic_num(request.args.get("max_price", "")),
                    "p_query": q or None,
                    "p_sort": sort_mode,
                    "p_offset": offset,
                    "p_limit": per_page + 1,
                },
            )
            if generic_rows is None:
                return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"generic_filter_unavailable"}), 503
            has_next = len(generic_rows) > per_page
            rows = generic_rows[:per_page]
        elif city != "all" and not has_combined_advanced_search and q:
            # Delegate text matching and pagination to the database function so
            # the API no longer downloads up to 10,000 listings for Python filtering.
            # Keep the old Python matcher above for category-filter branches, which
            # may still be used when callers combine q with category filters.
            offset = page * per_page
            search_rows = supabase_request(
                "POST",
                "rpc/mm_search_listings",
                payload={
                    "p_city_id": city_id,
                    "p_category_id": category_id,
                    "p_query": q,
                    "p_sort": sort_mode,
                    "p_offset": offset,
                    "p_limit": per_page + 1,
                },
            )
            if search_rows is None:
                return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"search_unavailable"}), 503
            has_next = len(search_rows) > per_page
            rows = search_rows[:per_page]
        elif not has_combined_advanced_search:
            offset = page * per_page
            if city == "all":
                # The cursor/search RPCs require a single city ID. For All, fetch
                # bounded candidates across cities, apply the same text matcher,
                # then sort and paginate the combined result set.
                all_params = dict(params)
                all_params.pop("offset", None)
                all_params.pop("limit", None)
                candidates = _fetch_listing_candidates(all_params, max_candidates=10000, batch_size=1000)
                if candidates is None:
                    return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"db_unavailable"}), 503
                rows = [r for r in candidates if _matches_search(r)]
                sort_mode = str(request.args.get("sort", "new")).strip().lower()
                if sort_mode == "price_asc":
                    rows.sort(key=lambda r: (r.get("price_usd") is None, float(r.get("price_usd") or 0), str(r.get("created_at") or "")), reverse=False)
                elif sort_mode == "price_desc":
                    rows.sort(key=lambda r: (r.get("price_usd") is None, float(r.get("price_usd") or 0), str(r.get("created_at") or "")), reverse=True)
                else:
                    rows.sort(key=lambda r: str(r.get("created_at") or ""), reverse=True)
                has_next = len(rows) > offset + per_page
                rows = rows[offset:offset + per_page]
            else:
                params["offset"] = str(offset)
                params["limit"] = str(per_page + 1)
                rows = supabase_request("GET", "listings", params=params)
                if rows is None:
                    return jsonify({"items":[],"has_next":False,"total_hint":0,"error":"db_unavailable"}), 503
                has_next = len(rows) > per_page
                rows = rows[:per_page]

    # Photos and favorite state are independent Supabase reads. Start the photo
    # query now so it can run while Telegram authentication/favorites are checked.
    _perf_photo_started = time.perf_counter()
    photo_future = LISTING_READ_EXECUTOR.submit(
        _supabase_photo_rows, [row.get("id") for row in rows]
    ) if rows else None

    # Favorite lookup is independent from photo lookup. Run both at once so
    # their network latency overlaps, while still waiting for both before the
    # response is assembled (favorite flags remain accurate).
    _perf_fav_started = time.perf_counter()
    def _load_favorite_ids():
        if not current_user_id or not rows:
            return set()
        listing_ids = [str(r.get("id")) for r in rows if r.get("id") is not None]
        if not listing_ids:
            return set()
        fav_rows = supabase_request(
            "GET",
            "favorites",
            params={
                "select":"listing_id",
                "user_id":f"eq.{current_user_id}",
                "listing_id":f"in.({','.join(listing_ids)})",
            },
        ) or []
        return {int(r["listing_id"]) for r in fav_rows if str(r.get("listing_id", "")).isdigit()}

    favorite_future = LISTING_READ_EXECUTOR.submit(_load_favorite_ids) if current_user_id and rows else None
    _perf_phase_started = time.perf_counter()
    photo_rows = photo_future.result() if photo_future is not None else []
    favorite_ids = favorite_future.result() if favorite_future is not None else set()
    print(f"PERF listings_phase=favorites_query ms={(time.perf_counter() - _perf_fav_started) * 1000:.1f} count={len(favorite_ids)}")
    print(f"PERF listings_phase=auth_favorites ms={(time.perf_counter() - _perf_fav_started) * 1000:.1f} rows={len(rows)}")
    photos_by_listing = {}
    for photo in photo_rows:
        listing_id = photo.get("listing_id")
        photo_url = photo.get("photo_url")
        if listing_id and photo_url:
            photos_by_listing.setdefault(listing_id, []).append(photo_url)
    items = []
    for row in rows:
        item = _row_to_listing(row)
        item["photos"] = photos_by_listing.get(row.get("id"), [])
        items.append(item)
    print(f"PERF listings_phase=attach_photos ms={(time.perf_counter() - _perf_phase_started) * 1000:.1f} rows={len(rows)}")
    for item in items:
        item["is_favorite"] = int(item.get("id", 0)) in favorite_ids
    for idx, item in enumerate(items):
        row = rows[idx]
        item["title"] = row.get("title") or item.get("title") or listing_title(item)
        item["description"] = row.get("description") or item.get("description") or ""
        item["price"] = str(row.get("price")) if row.get("price") is not None else item.get("price", "")
        item["currency"] = row.get("currency") or item.get("currency", "")
        item["address"] = row.get("address") or item.get("district", "")
        item["category_name"] = item.get("category") or "Объявление"
        if city == "all":
            _row_city_id = row.get("city_id")
            try:
                item["city_slug"] = city_ids_by_slug.get(int(_row_city_id), "")
            except (TypeError, ValueError):
                item["city_slug"] = ""
        else:
            item["city_slug"] = city
        _strip_public_listing_fields(item)
        _strip_listing_contact_fields(item)

    _perf_elapsed_ms = (time.perf_counter() - _perf_started) * 1000
    print(f"PERF listings_api ms={_perf_elapsed_ms:.1f} items={len(items)} city={city} category={category or 'all'} cursor={int(cursor_mode_active)}")
    response = jsonify({
        "items":items,
        "has_next":has_next,
        "total_hint":per_page * (page + 1) + (1 if has_next else 0),
        "cursor_mode": cursor_mode_active,
        "next_cursor_id": next_cursor_id,
    })
    response.headers["Server-Timing"] = f"app;dur={_perf_elapsed_ms:.1f}"
    return response


# ============================================================
# АВТОМАТИЧЕСКИЙ ЖИЗНЕННЫЙ ЦИКЛ ОБЪЯВЛЕНИЙ
# ============================================================

LISTING_LIFETIME_DAYS = 10
LISTING_REMINDER_DAYS_BEFORE_EXPIRY = 3
LISTING_PURGE_GRACE_DAYS = 2
LISTING_LIFECYCLE_INTERVAL_SECONDS = 15 * 60


def _storage_object_from_url(photo_ref):
    """Извлекает bucket и путь только из URL Supabase Storage; внешние URL пропускает."""
    value = str(photo_ref or "").strip()
    if not value.startswith(("http://", "https://")) or not SUPABASE_URL:
        return None
    try:
        parsed = urllib.parse.urlparse(value)
        base = urllib.parse.urlparse(SUPABASE_URL)
        if parsed.netloc != base.netloc:
            return None
        path = urllib.parse.unquote(parsed.path)
        parts = [part for part in path.split("/") if part]
        # Recognize object/public|sign|authenticated/bucket/path and render/image/public/bucket/path.
        if "object" in parts:
            idx = parts.index("object") + 1
            tail = parts[idx:]
            if tail and tail[0] in {"public", "sign", "authenticated"}:
                tail = tail[1:]
        elif "render" in parts:
            idx = parts.index("render") + 1
            tail = parts[idx:]
            if tail and tail[0] == "image":
                tail = tail[1:]
            if tail and tail[0] in {"public", "sign", "authenticated"}:
                tail = tail[1:]
        else:
            return None
        if len(tail) < 2:
            return None
        bucket = tail[0]
        object_path = "/".join(tail[1:])
        if not bucket or not object_path:
            return None
        return bucket, object_path
    except Exception as error:
        print("STORAGE URL PARSE ERROR:", repr(error))
        return None


def _delete_supabase_storage_photo(photo_ref):
    """Удаляет фото из Supabase Storage, не затрагивая Telegram IDs и внешние хосты."""
    object_ref = _storage_object_from_url(photo_ref)
    if not object_ref:
        return True
    bucket, object_path = object_ref
    url = f"{SUPABASE_URL}/storage/v1/object/{urllib.parse.quote(bucket, safe='')}/{urllib.parse.quote(object_path, safe='/')}"
    headers = {
        "apikey": SUPABASE_SECRET_KEY,
        "Authorization": f"Bearer {SUPABASE_SECRET_KEY}",
    }
    try:
        response = HTTP_SESSION.delete(url, headers=headers, timeout=(5, 20))
        if response.status_code in (200, 204, 404):
            return True
        print("STORAGE DELETE ERROR:", response.status_code, response.text[:300])
        return False
    except Exception as error:
        print("STORAGE DELETE ERROR:", repr(error))
        return False


def _listing_owner_telegram_id(user_id):
    if not user_id:
        return None
    owners = supabase_request(
        "GET", "users",
        params={"select":"id,telegram_id", "id":f"eq.{user_id}", "limit":"1"},
    )
    if not owners:
        return None
    return owners[0].get("telegram_id")


def _remind_listings_due_soon(now_iso, reminder_cutoff_iso):
    """Send separate 3/2/1-day reminders, grouped per owner and stage."""
    now = datetime.fromisoformat(str(now_iso).replace("Z", "+00:00"))
    stage_specs = (
        (3, "reminder_3_sent_at", 3),
        (2, "reminder_2_sent_at", 2),
        (1, "reminder_1_sent_at", 1),
    )
    sent_count = 0
    for days_left, marker, _ in stage_specs:
        lower = now + timedelta(days=days_left - 1)
        upper = now + timedelta(days=days_left)
        rows = supabase_request(
            "GET", "listings",
            params={
                "select":f"id,user_id,title,expires_at,{marker}",
                "status":"eq.published",
                "expires_at":f"gt.{lower.isoformat()}",
                "and":f"(expires_at.lte.{upper.isoformat()},{marker}.is.null)",
                "order":"expires_at.asc",
                "limit":"500",
            },
        )
        if rows is None:
            continue
        grouped = {}
        for row in rows:
            listing_id, user_id = row.get("id"), row.get("user_id")
            if not listing_id or not user_id:
                continue
            owner_telegram_id = _listing_owner_telegram_id(user_id)
            if owner_telegram_id:
                grouped.setdefault(str(owner_telegram_id), []).append(row)
        for owner_telegram_id, owner_rows in grouped.items():
            claimed_rows = []
            for row in owner_rows:
                claimed = supabase_request(
                    "PATCH", "listings",
                    params={"id":f"eq.{row.get('id')}", "status":"eq.published",
                            "expires_at":f"gt.{now_iso}", marker:"is.null"},
                    payload={marker:now_iso},
                )
                if claimed:
                    claimed_rows.append(row)
            if not claimed_rows:
                continue
            lines = [f"• {html.escape(str(row.get('title') or 'Ваше объявление'))}" for row in claimed_rows[:10]]
            if len(claimed_rows) > 10:
                lines.append(f"И ещё {len(claimed_rows) - 10} объявлений.")
            app_url = MINI_APP_URL + ("&" if "?" in MINI_APP_URL else "?") + "tab=my"
            text_value = (
                f"⏳ <b>До окончания публикации осталось {days_left} {'дня' if days_left in (2,3) else 'день'}!</b>\n\n"
                + "\n".join(lines)
                + "\n\nПродлите объявление на 10 дней во вкладке «Мои объявления», "
                  "если оно ещё актуально. После окончания срока оно будет снято с публикации, "
                  "а через 2 дня удалено окончательно."
            )
            result = api("sendMessage", {
                "chat_id":owner_telegram_id, "text":text_value, "parse_mode":"HTML",
                "disable_web_page_preview":True,
                "reply_markup":{"inline_keyboard":[[{"text":"📋 Мои объявления", "web_app":{"url":app_url}}]]},
            })
            if isinstance(result, dict) and result.get("ok"):
                sent_count += 1
                print("LISTING LIFECYCLE: reminder sent", {"owner":owner_telegram_id,"days_left":days_left,"listing_ids":[x.get("id") for x in claimed_rows]})
            else:
                description = result.get("description", "unknown error") if isinstance(result, dict) else "no response"
                print("LISTING LIFECYCLE: reminder failed", {"owner":owner_telegram_id,"days_left":days_left,"error":str(description)[:200]})
                for row in claimed_rows:
                    supabase_request("PATCH", "listings",
                        params={"id":f"eq.{row.get('id')}", marker:f"eq.{now_iso}"},
                        payload={marker:None})
    return sent_count


def _archive_expired_listings(now_iso):
    rows = supabase_request(
        "GET", "listings",
        params={
            "select":"id,status,channel_message_id,channel_url,metadata,expires_at",
            "status":"eq.published",
            "expires_at":f"lte.{now_iso}",
            "order":"expires_at.asc",
            "limit":"100",
        },
    )
    if rows is None:
        return 0
    archived = 0
    for row in rows:
        if not _delete_listing_channel_messages(row):
            # Keep it eligible so the worker retries; catalog/API filters already hide it by expiry.
            continue
        updated = supabase_request(
            "PATCH", "listings",
            params={"id":f"eq.{row.get('id')}", "status":"eq.published", "expires_at":f"lte.{now_iso}"},
            payload={"status":"archived", "channel_url":"", "channel_message_id":None},
        )
        if updated is not None:
            archived += 1
    return archived


def _purge_expired_listings(purge_cutoff_iso):
    rows = supabase_request(
        "GET", "listings",
        params={
            "select":"id,status,channel_message_id,channel_url,metadata,expires_at",
            "status":"eq.archived",
            "expires_at":f"lte.{purge_cutoff_iso}",
            "order":"expires_at.asc",
            "limit":"100",
        },
    )
    if rows is None:
        return 0
    deleted_count = 0
    for row in rows:
        # A previously published Telegram post can remain in metadata as a list of IDs.
        if not _delete_listing_channel_messages(row):
            continue
        listing_id = row.get("id")
        photo_rows = supabase_request(
            "GET", "listing_photos",
            params={"select":"photo_url", "listing_id":f"eq.{listing_id}", "limit":"100"},
        )
        if photo_rows is None:
            continue
        storage_ok = all(_delete_supabase_storage_photo(photo.get("photo_url")) for photo in photo_rows)
        if not storage_ok:
            # Keep the DB rows so failed Storage deletions can be retried next cycle.
            continue
        photos_deleted = supabase_request("DELETE", "listing_photos", params={"listing_id":f"eq.{listing_id}"})
        if photos_deleted is None:
            continue
        deleted = supabase_request(
            "DELETE", "listings",
            params={"id":f"eq.{listing_id}", "status":"eq.archived", "expires_at":f"lte.{purge_cutoff_iso}"},
        )
        if deleted is not None:
            deleted_count += 1
    return deleted_count


def run_listing_lifecycle_once():
    """One idempotent maintenance pass; safe to retry after process restarts."""
    if not supabase_enabled():
        return {"reminded":0,"archived":0,"deleted":0}
    now = datetime.now(timezone.utc)
    now_iso = now.isoformat()
    reminder_cutoff_iso = (now + timedelta(days=LISTING_REMINDER_DAYS_BEFORE_EXPIRY)).isoformat()
    purge_cutoff_iso = (now - timedelta(days=LISTING_PURGE_GRACE_DAYS)).isoformat()
    result = {"reminded":0,"archived":0,"deleted":0}
    try:
        result["reminded"] = _remind_listings_due_soon(now_iso, reminder_cutoff_iso)
        result["archived"] = _archive_expired_listings(now_iso)
        result["deleted"] = _purge_expired_listings(purge_cutoff_iso)
        print("LISTING LIFECYCLE PASS:", result)
    except Exception as error:
        print("LISTING LIFECYCLE ERROR:", repr(error))
    return result


def _listing_lifecycle_loop():
    # Small startup delay lets Flask/Gunicorn finish initializing before maintenance starts.
    time.sleep(30)
    while True:
        run_listing_lifecycle_once()
        time.sleep(LISTING_LIFECYCLE_INTERVAL_SECONDS)


def start_listing_lifecycle_worker():
    worker = threading.Thread(target=_listing_lifecycle_loop, name="listing-lifecycle", daemon=True)
    worker.start()


@app.get("/api/listing/<int:listing_id>")
def mini_app_listing_detail(listing_id):
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    rows = supabase_request(
        "GET",
        "listings",
        params={
            "select":"id,user_id,title,description,price,currency,address,metadata,channel_url,created_at,category_id,city_id,status,phone,whatsapp,telegram",
            "id":f"eq.{listing_id}",
            "status":"eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "limit":"1",
        },
    )
    if not rows:
        return jsonify({"error":"not_found"}), 404
    item = _attach_catalog_photos(rows)[0]
    row = rows[0]
    seller_id = row.get("user_id")
    item["seller"] = None
    if seller_id is not None:
        seller_rows = supabase_request(
            "GET", "users",
            params={"select":"id,first_name,last_name","id":f"eq.{seller_id}","limit":"1"},
        ) or []
        if seller_rows:
            seller_row = seller_rows[0]
            seller_name = " ".join(str(seller_row.get(k) or "").strip() for k in ("first_name","last_name")).strip()
            item["seller"] = {
                "id": int(seller_row["id"]),
                "name": seller_name or None,
            }
    item["title"] = row.get("title") or item.get("title") or listing_title(item)
    item["description"] = row.get("description") or item.get("description") or ""
    item["price"] = str(row.get("price")) if row.get("price") is not None else item.get("price", "")
    item["currency"] = row.get("currency") or item.get("currency", "")
    item["address"] = row.get("address") or item.get("district", "")
    item["phone"] = row.get("phone") or item.get("phone", "") or ""
    item["whatsapp"] = row.get("whatsapp") or item.get("whatsapp", "") or ""
    item["telegram"] = row.get("telegram") or item.get("telegram", "") or ""
    item["category_name"] = item.get("category") or "Объявление"
    current_user=_mini_app_authenticated_user()
    if current_user:
        _track_mm_event("listing_view", current_user.get("id"), listing_id)
    item["is_favorite"]=False
    if current_user:
        current_user_id=_supabase_user_id(current_user.get("id"))
        if current_user_id:
            fav=supabase_request("GET","favorites",params={"select":"id","user_id":f"eq.{current_user_id}","listing_id":f"eq.{listing_id}","limit":"1"}) or []
            item["is_favorite"]=bool(fav)
    _strip_public_listing_fields(item)
    return jsonify(item)


@app.get("/api/seller/<int:seller_id>")
def mini_app_seller_profile(seller_id):
    """Public seller profile with safe fields and currently published listings only."""
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    if seller_id <= 0:
        return jsonify({"error":"not_found"}), 404

    users = supabase_request(
        "GET", "users",
        params={"select":"id,first_name,last_name,created_at","id":f"eq.{seller_id}","limit":"1"},
    ) or []
    if not users:
        return jsonify({"error":"not_found"}), 404

    now_iso = _utc_now_iso()
    active_filter = {
        "user_id":f"eq.{seller_id}",
        "status":"eq.published",
        "expires_at":f"gt.{now_iso}",
    }
    count_rows = supabase_request(
        "GET", "listings",
        params={"select":"id", **active_filter, "limit":"1001"},
    ) or []
    active_count = len(count_rows)
    active_count_label = "1000+" if active_count >= 1000 else active_count

    listing_rows = supabase_request(
        "GET", "listings",
        params={
            "select":"id,title,description,price,currency,address,metadata,channel_url,created_at,published_at,category_id,city_id",
            **active_filter,
            "order":"created_at.desc",
            "limit":"21",
        },
    ) or []
    has_more = len(listing_rows) > 20
    listing_rows = listing_rows[:20]
    items = _attach_catalog_photos(listing_rows) if listing_rows else []
    for item in items:
        item["category_name"] = item.get("category") or "Объявление"
        _strip_public_listing_fields(item)
        _strip_listing_contact_fields(item)

    user = users[0]
    seller_name = " ".join(str(user.get(k) or "").strip() for k in ("first_name","last_name")).strip()
    return jsonify({
        "seller":{
            "id":int(user["id"]),
            "name":seller_name or None,
            "first_name":user.get("first_name"),
            "last_name":user.get("last_name"),
            "created_at":user.get("created_at"),
        },
        "active_count":active_count,
        "active_count_label":active_count_label,
        "items":items,
        "has_more":has_more,
    })


@app.get("/media/<int:listing_id>/<int:index>")
def mini_app_media(listing_id, index):
    _perf_started = time.perf_counter()
    if index < 0 or index >= MAX_PHOTOS:return "Not found",404

    # Fetch publication/expiry state and the ordered photo list in one
    # PostgREST request. The previous implementation made two database
    # round trips for every card photo, adding latency when a page has 20 cards.
    joined = supabase_request(
        "GET", "listings",
        params={
            "select": "id,listing_photos(photo_url,sort_order)",
            "id": f"eq.{listing_id}",
            "status": "eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "limit": "1",
        },
    )
    if joined is not None:
        if not joined:
            return "Not found", 404
        rows = joined[0].get("listing_photos") or []
        rows = sorted(rows, key=lambda row: row.get("sort_order") or 0)
    else:
        # Compatibility fallback if the project's PostgREST relationship
        # metadata does not support embedding listing_photos in this query.
        published = supabase_request(
            "GET", "listings",
            params={"select":"id","id":f"eq.{listing_id}","status":"eq.published","expires_at":f"gt.{_utc_now_iso()}","limit":"1"},
        )
        if not published:
            return "Not found", 404
        rows = supabase_request(
            "GET", "listing_photos",
            params={"select":"photo_url,sort_order","listing_id":f"eq.{listing_id}","order":"sort_order.asc"},
        )
        if rows is None:
            return "Not found", 404

    if index >= len(rows):return "Not found",404
    photo_ref=str(rows[index].get("photo_url") or "")
    if not photo_ref:return "Not found",404
    try:
        if photo_ref.startswith("http://") or photo_ref.startswith("https://"):
            # Treat photo_url as untrusted data: only fetch HTTPS URLs from the
            # configured Supabase host. This prevents the media proxy from being
            # used to request localhost, cloud metadata, or arbitrary internal URLs.
            photo_url = urllib.parse.urlparse(photo_ref)
            supabase_host = urllib.parse.urlparse(SUPABASE_URL).hostname
            if (
                photo_url.scheme != "https"
                or not photo_url.hostname
                or not supabase_host
                or photo_url.hostname.lower() != supabase_host.lower()
                or photo_url.username is not None
                or photo_url.password is not None
                or photo_url.port not in (None, 443)
            ):
                return "Not found", 404
            upstream=requests.get(photo_ref,timeout=15,allow_redirects=False)
            if 300 <= upstream.status_code < 400:
                return "Not found",404
        else:
            file_info=api("getFile",{"file_id":photo_ref});result=file_info.get("result") if isinstance(file_info,dict) else None;file_path=result.get("file_path") if isinstance(result,dict) else None
            if not file_path:return "Not found",404
            upstream=requests.get(f"https://api.telegram.org/file/bot{BOT_TOKEN}/{file_path}",timeout=20)
        if not upstream.ok:return "Not found",404
        _perf_elapsed_ms = (time.perf_counter() - _perf_started) * 1000
        print(f"PERF media ms={_perf_elapsed_ms:.1f} listing_id={listing_id} index={index} bytes={len(upstream.content)}")
        return Response(upstream.content,content_type=upstream.headers.get("Content-Type","image/jpeg"),headers={"Cache-Control":"public, max-age=86400","X-Content-Type-Options":"nosniff","Server-Timing":f"app;dur={_perf_elapsed_ms:.1f}"})
    except Exception as error:
        print("MEDIA ERROR:",repr(error));return "Media unavailable",503


def restore_moderation_counter():
    global next_moderation_id
    found, payload, ok = runtime_state_load("meta:next_moderation_id")
    if not ok or not found or not isinstance(payload, dict):
        return
    try:
        next_moderation_id = max(1, int(payload.get("value", 1)))
    except (TypeError, ValueError):
        print("RUNTIME STATE WARNING: invalid moderation counter; using 1")


restore_moderation_counter()


