@app.get("/")
def home():

    return (
        "MADLOBA MARKET BOT is running."
    )


@app.post("/webhook")
def webhook():
    # Reject requests that do not carry Telegram's configured webhook secret.
    if not WEBHOOK_SECRET:
        print("WEBHOOK SECURITY ERROR: WEBHOOK_SECRET is not configured")
        return "Webhook secret not configured", 503

    supplied_secret = request.headers.get(
        "X-Telegram-Bot-Api-Secret-Token",
        ""
    )
    if not hmac.compare_digest(supplied_secret, WEBHOOK_SECRET):
        return "Forbidden", 403

    update = request.get_json(silent=True)
    if not isinstance(update, dict):
        return "Bad Request", 400

    update_id = update.get("update_id")
    if update_id is not None:
        claimed = claim_telegram_update(update_id)
        if claimed is False:
            # Telegram redelivered an update already claimed by this bot.
            return "OK"
        if claimed is None:
            # Fail open during a transient database issue so the bot remains usable.
            # The warning makes it visible that deduplication was not available.
            print("TELEGRAM UPDATE DEDUP WARNING: processing without deduplication", update_id)

    try:
        handle(update)
    except Exception as error:
        print("UPDATE ERROR:", repr(error))

    return "OK"


